local config = {
  ui_story_5088_50880100_1_dialog_content = "<color=#e8d9bb>Please recall that long-forgotten story.</color>",
  ui_story_5088_50880100_2_dialog_content = "<color=#e8d9bb>The story of an ancient kingdom on the brink of disaster, and the arrival of a band of heroes—</color>",
  ui_story_5088_50880100_3_dialog_content = "<color=#e8d9bb>To save their kingdom from a vile presence, they willingly underwent dangerous augmentations.</color>",
  ui_story_5088_50880100_4_dialog_content = "<color=#e8d9bb>But when peace was restored once more, the heroes were cursed and reviled as monsters, both in body and mind.</color>",
  ui_story_5088_50880100_5_dialog_content = "<color=#e8d9bb>Framed by the priests, forsaken by the king, and feared by the ignorant masses they swore to protect.</color>",
  ui_story_5088_50880100_6_dialog_content = "<color=#e8d9bb>In their unfathomable desperation, the heroes looked to each other for warmth and solace, yet there was no resisting the corruption of their curse.</color>",
  ui_story_5088_50880100_7_dialog_content = "<color=#e8d9bb>To grant them one last chance at happiness, their leader and a dear friend sacrificed themselves.</color>",
  ui_story_5088_50880100_8_dialog_content = "<color=#e8d9bb>Sealed beyond the flow of time, they waited in silence—</color>",
  ui_story_5088_50880100_9_dialog_content = "Huff, puff...",
  ui_story_5088_50880100_10_dialog_content = "Graaaaah!",
  ui_story_5088_50880100_11_dialog_content = "<color=#e8d9bb>Day One: A Great Calamity Descends.</color>",
  ui_story_5088_50880100_12_dialog_content = "This is bad! They're catching up—",
  ui_story_5088_50880100_13_dialog_content = "Not on my watch!",
  ui_story_5088_50880100_14_dialog_content = "It's you... The one from the royal capital's celebration...",
  ui_story_5088_50880100_15_dialog_content = "Can you walk? Here, take my hand.",
  ui_story_5088_50880100_16_dialog_content = "... That hero.",
  ui_story_5088_50880100_17_dialog_content = "I'm no hero, you can call me Adras.",
  ui_story_5088_50880100_18_dialog_content = "<color=#e8d9bb>Day Two: Heroes of Destiny.</color>",
  ui_story_5088_50880100_19_dialog_content = "What happened?",
  ui_story_5088_50880100_20_dialog_content = "Nothing, I was just helping this traveler.",
  ui_story_5088_50880100_21_dialog_content = "Are you alright?",
  ui_story_5088_50880100_22_dialog_content = "The town is safe, and no casualties have been reported. We can rest there for now.",
  ui_story_5088_50880100_23_dialog_content = "<color=#e8d9bb>Day Three: Praising the Stars</color>",
  ui_story_5088_50880100_24_dialog_content = "Pardon me, but...",
  ui_story_5088_50880100_25_dialog_content = "Oh! I haven't even introduced myself yet.",
  ui_story_5088_50880100_26_dialog_content = "My name is—",
  ui_story_5088_50880100_27_dialog_content = "<color=#e8d9bb>Day Four: Peace, Change, and Tension.</color>",
  ui_story_5088_50880100_28_dialog_content = "Achilles... My head is spinning...",
  ui_story_5088_50880100_29_dialog_content = "I'm so sorry, my friend... But I have to keep you here...",
  ui_story_5088_50880100_30_dialog_content = "Save your strength. I'll take you to a medic right away.",
  ui_story_5088_50880100_31_dialog_content = "N-No, that won't be necessary. I'm so tired... And I miss my home so dearly...",
  ui_story_5088_50880100_32_dialog_content = "Then let me take you home.",
  ui_story_5088_50880100_33_dialog_content = "Not another step, Claymore! Was murdering Lord Lucius and rebelling against the Elder Council not enough for you?! Surrender, you monster!",
  ui_story_5088_50880100_34_dialog_content = "... Stand aside. I will not raise my blade against the innocent.",
  ui_story_5088_50880100_35_dialog_content = "Then you'll pay with the blood you owe to the High Priest!",
  ui_story_5088_50880100_36_dialog_content = "<size=45>I said stand aside!</size>",
  ui_story_5088_50880100_37_dialog_content = "Urgh... I-I can't move my legs... What's this...?!",
  ui_story_5088_50880100_38_dialog_content = "What's happening, Achilles...? I can't see the color of your light anymore...",
  ui_story_5088_50880100_39_dialog_content = "It's nothing, Ludweiss. Here, give me your hand. It's time to go back.",
  ui_story_5088_50880100_40_dialog_content = "No, wait, I remember now... Our friends are far more important. They're still sealed away, so please take them and go...",
  ui_story_5088_50880100_41_dialog_content = "We're here, Lord Achilles!",
  ui_story_5088_50880100_42_dialog_content = "What... What on earth happened here...?",
  ui_story_5088_50880100_43_dialog_content = "Anthony... Why do you insist on meddling with monsters like ourselves?",
  ui_story_5088_50880100_44_dialog_content = "I have no idea what you're talking about, Lord Achilles. All I know is that you need my help.",
  ui_story_5088_50880100_45_dialog_content = "... Take good care of Adras and the others.",
  ui_story_5088_50880100_46_dialog_content = "I'll create an opening to escape.",
  ui_story_5088_50880100_47_dialog_content = "Let's go, Ludweiss.",
  ui_story_5088_50880100_48_dialog_content = "Is it over? Has the Elder Council ended their revolt? I wonder... Will the children suffer because of this...?",
  ui_story_5088_50880100_49_dialog_content = "It will all be over soon, Ludweiss. Just keep talking to me.",
  ui_story_5088_50880100_50_dialog_content = "Tell me more about your home. I remember you once described it as a paradise of sorts.",
  ui_story_5088_50880100_51_dialog_content = "No, my people never set foot in that place... We're all just lost exiles... Trying desperately to return to the paradise of our ancestors...",
  ui_story_5088_50880100_52_dialog_content = "In the past, I could only recall the beauty of Eraveil through the memories of my ancestors... But now... I finally found it...",
  ui_story_5088_50880100_53_dialog_content = "The voice in my dreams... It belongs to a boy from Eraveil.",
  ui_story_5088_50880100_54_dialog_content = "How I wish to see the place myself.",
  ui_story_5088_50880100_55_dialog_content = "Then we'll go to Eraveil together. You, me, and the rest of us.",
  ui_story_5088_50880100_56_dialog_content = "I'm so sorry... I wanted to save you too, but it's too late now...",
  ui_story_5088_50880100_57_dialog_content = "Your light has been devoured. You can't go on like this...",
  ui_story_5088_50880100_58_dialog_content = "Don't worry yourself for my sake.",
  ui_story_5088_50880100_59_dialog_content = "I swear I'll fulfill your prophecy, and take you to see the beauty of your home in person.",
  ui_story_5088_50880100_60_dialog_content = "If that's how you feel... Then I'm placing all of my trust in you.",
  ui_story_5088_50880100_61_dialog_content = "With only the power of the Fallen Star left, it falls to you to make that miracle come true.",
  ui_story_5088_50880100_62_dialog_content = "Never lose your faith in hope, for it will guide you out of this darkness someday.",
  ui_story_5088_50880100_63_dialog_content = "It's all up to you now... Achilles...",
  ui_story_5088_50880100_64_dialog_content = "...",
  ui_story_5088_50880100_65_dialog_content = "...",
  ui_story_5088_50880100_66_dialog_content = [[
<color=#e8d9bb>And this is the end of this doomed and tragic story.  
Alone in the world, the hero begins his endless journey...</color>]],
  ui_story_5088_50880100_67_dialog_content = "No, not this one... This isn't it, either...",
  ui_story_5088_50880100_68_dialog_content = "I know you're in a hurry, my dear, but please be a bit more careful when handling the merchandise. They're antiques, after all.",
  ui_story_5088_50880100_69_dialog_content = "Really? Because I recall you using that journal to line a treasure chest before you sold it to me.",
  ui_story_5088_50880100_70_dialog_content = "That's only because it was already a defective item. The writing on it was basically incomprehensible.",
  ui_story_5088_50880100_71_dialog_content = "And yet it still holds value for you, doesn't it?",
  ui_story_5088_50880100_72_dialog_content = "Another shipment for you, boss.",
  ui_story_5088_50880100_73_dialog_content = "Excellent work, Casta. Anywhere will do, thank you.",
  ui_story_5088_50880100_74_dialog_content = "...",
  ui_story_5088_50880100_75_dialog_content = "PlayerName? You looking for something?",
  ui_story_5088_50880100_76_dialog_content = "It's a long story... You see, I let Sheol sweet-talk me into rummaging through antiques because she said I could make a fortune if I'm lucky.",
  ui_story_5088_50880100_77_dialog_content = "But when I started sensing some of them, I stumbled across an ancient notebook left behind by one of my people.",
  ui_story_5088_50880100_78_dialog_content = "I'm really interested to learn more about it... And even though it's barely legible, I want to keep searching for stuff like this.",
  ui_story_5088_50880100_79_dialog_content = "I have to help them... I have to find even more memories for my friends.",
  ui_story_5088_50880100_80_dialog_content = "So you came to Lady Sheol for help?",
  ui_story_5088_50880100_81_dialog_content = "Yes he did, but time is money, so please continue searching.",
  ui_story_5088_50880100_82_dialog_content = "There's so much stuff lying around here. Are you sure you're not just making it harder for him?",
  ui_story_5088_50880100_83_dialog_content = "I can definitely sense something similar coming from one of these antiques... But there's just too many of them.",
  ui_story_5088_50880100_84_dialog_content = "*coughs* My, just look at all this dust... It's not that I don't want to help you, my dear. These items are simply far too old, and tracing their origins is almost impossible.",
  ui_story_5088_50880100_85_dialog_content = "If I hadn't brought them in for safekeeping, someone else in Umbraton would have likely broken them by now.",
  ui_story_5088_50880100_86_dialog_content = "Then again, I'm no expert on these things. Ah, if only Vergil was here to sort them out.",
  ui_story_5088_50880100_87_dialog_content = "Here, let me help—There you go.",
  ui_story_5088_50880100_88_dialog_content = "Uh... Aren't you just grabbing stuff at random?",
  ui_story_5088_50880100_89_dialog_content = "When hard work can't get the job done, you have to rely on your luck and intuition.",
  ui_story_5088_50880100_90_dialog_content = "Trust me.",
  ui_story_5088_50880100_91_dialog_content = "Th-This is...",
  ui_story_5088_50880100_92_dialog_content = "Huh? Oh my, it actually worked.",
  ui_story_5088_50880100_93_dialog_content = "There's no mistaking it. This is a Star Crest!",
  ui_story_5088_50880100_94_dialog_content = "It's exactly what I was looking for!",
  ui_story_5088_50880100_95_dialog_content = "Good to hear.",
  ui_story_5088_50880100_96_dialog_content = "Since it appears to hold much value for you, I'll let you keep it free of charge.",
  ui_story_5088_50880100_97_dialog_content = "I have no use for it here, so consider it a gift for my number-one customer.",
  ui_story_5088_50880100_98_dialog_content = "Thank you so much, Lady Sheol!",
  ui_story_5088_50880100_99_dialog_content = "I have to go now. See you!",
  ui_story_5088_50880100_100_dialog_content = "It's already dark out. Let me walk you back.",
  ui_story_5088_50880100_101_dialog_content = "Ouch—",
  ui_story_5088_50880100_102_dialog_content = "Ah! I-I'm sorry, I didn't mean to... Tweety?",
  ui_story_5088_50880100_103_dialog_content = "Hey! It's you, Mr. Navigator!",
  ui_story_5088_50880100_104_dialog_content = "Sorry about that, I was in too much of a hurry just now.",
  ui_story_5088_50880100_105_dialog_content = "Are you alright, ma'am?",
  ui_story_5088_50880100_106_dialog_content = "Oh good, none of the letters went missing.",
  ui_story_5088_50880100_107_dialog_content = "\"Ma'am\"?",
  ui_story_5088_50880100_108_dialog_content = "Let me to intwoduce our newest Courier! She's pwetty tawented, you know!",
  ui_story_5088_50880100_109_dialog_content = "Nice to meet you all. My name is Mithra, and I've been assigned to Miss Tweety as her assistant.",
  ui_story_5088_50880100_110_dialog_content = "This feels completely off... You're so much taller than her.",
  ui_story_5088_50880100_111_dialog_content = "Heehee...",
  ui_story_5088_50880100_112_dialog_content = "Sorry everyone, but I really have to go! I'll make sure to apologize to you properly later, Tweety!",
  ui_story_5088_50880100_113_dialog_content = "See you awound, Mr. Navigator!",
  ui_story_5088_50880100_114_dialog_content = "Are you sure there's nothing else?",
  ui_story_5088_50880100_115_dialog_content = "Is this all you can remember?",
  ui_story_5088_50880100_116_dialog_content = "For a certain reason, you spent most of your time living in the city where you were stationed.",
  ui_story_5088_50880100_117_dialog_content = "Just forget about it. Remembering these things won't do you any good now.",
  ui_story_5088_50880100_118_dialog_content = "I don't care if it hurts. I have to regain my memories.",
  ui_story_5088_50880100_119_dialog_content = "I can still remember her... My love... But for some reason, I can't even remember her face...",
  ui_story_5088_50880100_120_dialog_content = "It was only because of her that I swore to protect the righteous with my blade.",
  ui_story_5088_50880100_121_dialog_content = "So please, at least tell me her name!",
  ui_story_5088_50880100_122_dialog_content = "Ta-daaa! Well? Did my graceful entrance take you by surprise?",
  ui_story_5088_50880100_123_dialog_content = "Hey! You guys started without me!",
  ui_story_5088_50880100_124_dialog_content = "It's your fault for being so slow.",
  ui_story_5088_50880100_125_dialog_content = "I didn't miss anything, did I?",
  ui_story_5088_50880100_126_dialog_content = "...",
  ui_story_5088_50880100_127_dialog_content = "Sorry, but I don't remember anything either.",
  ui_story_5088_50880100_128_dialog_content = "I see...",
  ui_story_5088_50880100_129_dialog_content = "Then what about that other name? \"Claymore\"?",
  ui_story_5088_50880100_130_dialog_content = "?!",
  ui_story_5088_50880100_131_dialog_content = "How dare you bring up that person's name again!",
  ui_story_5088_50880100_132_dialog_content = "Hey, settle down already!",
  ui_story_5088_50880100_133_dialog_content = "Let go of me—! We agreed to never mention him again!",
  ui_story_5088_50880100_134_dialog_content = "You dismembered that person yourself that day.",
  ui_story_5088_50880100_135_dialog_content = "Is this why you gathered us here today? To make us remember the pain again?!",
  ui_story_5088_50880100_136_dialog_content = "I... I hated that person. Somehow I just did, and I don't know why...",
  ui_story_5088_50880100_137_dialog_content = "But when PlayerName showed me, it only convinced me even more... That person...",
  ui_story_5088_50880100_138_dialog_content = "His name was Achilles, and he was our leader.",
  ui_story_5088_50880100_139_dialog_content = "Yeah? So what?",
  ui_story_5088_50880100_140_dialog_content = "He was your general, and the leader of our group.",
  ui_story_5088_50880100_141_dialog_content = "But he betrayed us.",
  ui_story_5088_50880100_142_dialog_content = "The truth is, we all agreed on it—on letting ourselves be destroyed.",
  ui_story_5088_50880100_143_dialog_content = "But when his blade pierced my heart, I felt... resentment.",
  ui_story_5088_50880100_144_dialog_content = "I was so relieved to be able to feel something after all... But soon I realized... The pain wasn't going away.",
  ui_story_5088_50880100_145_dialog_content = "The captain was once a great hero, and a good friend to us all. Putting an end to his suffering is the least we can do.",
  ui_story_5088_50880100_146_dialog_content = "That's right. He was a hero... And I owed him my life.",
  ui_story_5088_50880100_147_dialog_content = "That's why... It felt even more hatred when he suddenly attacked.",
  ui_story_5088_50880100_148_dialog_content = "It shouldn't be like this... I know I shouldn't hate him...",
  ui_story_5088_50880100_149_dialog_content = "Maybe we're forgetting something important?",
  ui_story_5088_50880100_150_dialog_content = "For example... Were there really only five of us back then?",
  ui_story_5088_50880100_151_dialog_content = "I want to remember everything.",
  ui_story_5088_50880100_152_dialog_content = "What happened to us in the past? And what happened when we finally reawakened?",
  ui_story_5088_50880100_153_dialog_content = "What exactly have we forgotten? Will we ever remember it all?",
  ui_story_5088_50880100_154_dialog_content = "<size=30>The person we can't remember is the one who recorded everything about us. Forgive us... Our long-forgotten friend.</size>",
  ui_story_5088_50880100_155_dialog_content = "I can sense the presence of Aurorians deep inside this frozen cave... But how? Is this why the queen asked me to investigate?",
  ui_story_5088_50880100_156_dialog_content = "Just hang on! I'll get you guys out of there...",
  ui_story_5088_50880100_157_dialog_content = "Everything is in place now. The seal will only be broken once a Caelestite decides to free them from this place.",
  ui_story_5088_50880100_158_dialog_content = "In exchange, it will trap me here and slowly drain my strength. But even if I become an Eclipsite, I'll continue to watch over them.",
  ui_story_5088_50880100_159_dialog_content = "Was that...?",
  ui_story_5088_50880100_160_dialog_content = "Captain... Why...",
  ui_story_5088_50880100_161_dialog_content = "Did I...?",
  ui_story_5088_50880100_162_dialog_content = "Huh? I'm still alive?",
  ui_story_5088_50880100_163_dialog_content = "Hey... What's that light coming from down there? Has the seal been activated already?",
  ui_story_5088_50880100_164_dialog_content = "This formation... Is this the place from before? The cave where that man...",
  ui_story_5088_50880100_165_dialog_content = "A... A Caelestite?",
  ui_story_5088_50880100_166_dialog_content = "Grah!!!",
  ui_story_5088_50880100_167_dialog_content = "Argh... My head... What's happening? Why do I suddenly hear so many voices?!",
  ui_story_5088_50880100_168_dialog_content = "No—Go away! Leave me alone!",
  ui_story_5088_50880100_169_dialog_content = "A-Are you okay?",
  ui_story_5088_50880100_170_dialog_content = "That voice... he's still alive!",
  ui_story_5088_50880100_171_dialog_content = "Claymore... The defender of the kingdom is going to destroy us all!",
  ui_story_5088_50880100_172_dialog_content = "Hey! Now's not the time to be thinking about that!",
  ui_story_5088_50880100_173_dialog_content = "This boy saved us, but it looks like he's in really bad shape.",
  ui_story_5088_50880100_174_dialog_content = "Saving people comes first, just as always. We'll figure out the rest later.",
  ui_story_5088_50880100_175_dialog_content = "... Then let's go.",
  ui_story_5088_50880100_176_dialog_content = "He's coming after us.",
  ui_story_5088_50880100_177_dialog_content = "Magic of the forest, hide us from the eyes of our pursuer—Go!",
  ui_story_5088_50880100_178_dialog_content = "Th-There's no escape!",
  ui_story_5088_50880100_179_dialog_content = "<size=45>Death to all enemies!!!</size>",
  ui_story_5088_50880100_180_dialog_content = "<color=#e8d9bb>A surge of raw power bursts forth, ripping through the dense, magical branches.</color>",
  ui_story_5088_50880100_181_dialog_content = "It hurts...",
  ui_story_5088_50880100_182_dialog_content = "A Caelestite... I must spare him...",
  ui_story_5088_50880100_183_dialog_content = "<color=#e8d9bb>The energy from the massive sword cleaves the ground as it surges towards the group.</color>",
  ui_story_5088_50880100_184_dialog_content = "<color=#e8d9bb>But at the very last second, the Eclipsite diverts his overwhelming power away from them.</color>",
  ui_story_5088_50880100_185_dialog_content = "<color=#e8d9bb>Silently, he watches as his quarry escapes.</color>",
  ui_story_5088_50880100_186_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50880201_1_dialog_content = "(This emblem is different from the ones that Adras and the others carry. It has a unique image engraved on it.)",
  ui_story_5088_50880201_2_dialog_content = "Could it be Claymore's...?",
  ui_story_5088_50880201_3_dialog_content = "(I can definitely sense his power coming from it.)",
  ui_story_5088_50880201_4_option_content = "Psychic Scan",
  ui_story_5088_50880201_5_dialog_content = "<color=#e8d9bb>Day Five: And the Traitor Said, \"The Heroes Shall Die.\"</color>",
  ui_story_5088_50880201_6_dialog_content = "Out of my way!",
  ui_story_5088_50880201_7_dialog_content = "Creak—Creak—",
  ui_story_5088_50880201_8_dialog_content = "... I see.",
  ui_story_5088_50880201_9_dialog_content = "They're Eclipsites now...",
  ui_story_5088_50880201_10_dialog_content = "They were brave and loyal soldiers, but you twisted them into monsters.",
  ui_story_5088_50880201_11_dialog_content = "And now, only another monster like me can put an end to their suffering.",
  ui_story_5088_50880201_12_dialog_content = "There was no other choice.",
  ui_story_5088_50880201_13_dialog_content = "Can you still call yourself \"king\" now?",
  ui_story_5088_50880201_14_dialog_content = "Or a person, for that matter?",
  ui_story_5088_50880201_15_dialog_content = "<size=45>Gaius Agamemnon!!!</size>",
  ui_story_5088_50880201_16_dialog_content = "Come down from your rotten throne and face me!",
  ui_story_5088_50880202_1_dialog_content = "What... What in the world...",
  ui_story_5088_50880202_2_dialog_content = "Lord Achilles... Don't tell me you've lost your mind as well?",
  ui_story_5088_50880202_3_dialog_content = "...",
  ui_story_5088_50880202_4_dialog_content = "Beyond us sits the king. We cannot allow you to pass.",
  ui_story_5088_50880202_5_dialog_content = "If any of you still see me as Achilles, then please stand aside.",
  ui_story_5088_50880202_6_dialog_content = "I have something to say to that man.",
  ui_story_5088_50880202_7_dialog_content = "But...",
  ui_story_5088_50880202_8_dialog_content = "Let him pass.",
  ui_story_5088_50880202_9_dialog_content = "You couldn't stop him even if you tried. There's no need to sacrifice yourselves so pointlessly.",
  ui_story_5088_50880202_10_dialog_content = "Yes, Your Majesty!",
  ui_story_5088_50880202_11_dialog_content = "This way, Lord Achilles...",
  ui_story_5088_50880202_12_dialog_content = "... None of my comrades ever lost their minds. Remember that.",
  ui_story_5088_50880202_13_dialog_content = "You've suffered so much just to survive until now, Achilles. Why not let things end as they should?",
  ui_story_5088_50880202_14_dialog_content = "My comrades and I... don't care about becoming martyrs.",
  ui_story_5088_50880202_15_dialog_content = "But I know they deserve a much better ending, and I'm willing to trade my life to give it to them.",
  ui_story_5088_50880202_16_dialog_content = "But from the moment your guards drew their swords at me... I realized you never intended to let us live.",
  ui_story_5088_50880202_17_dialog_content = "My loyalty to you ends today.",
  ui_story_5088_50880202_18_dialog_content = "What makes you say that? Could it be... because of the dead Caelestite you're carrying on your back?",
  ui_story_5088_50880202_19_dialog_content = "Well, you can keep her. Besides, I knew this day would eventually come.",
  ui_story_5088_50880202_20_dialog_content = "You and your comrades owe me nothing. If anything, I am indebted to you.",
  ui_story_5088_50880202_21_dialog_content = "But we all know perfectly well that I was right to do the things I've done.",
  ui_story_5088_50880202_22_dialog_content = "I seek your eradication not out of personal desire, but for the sake of the hard-won peace that our kingdom now enjoys.",
  ui_story_5088_50880202_23_dialog_content = "You... How could you say that?!",
  ui_story_5088_50880202_24_dialog_content = "I sacrificed all that I held dear to me, and our kingdom is now at peace because of it.",
  ui_story_5088_50880202_25_dialog_content = "I will always remember every drop of blood you and your comrades shed for our nation.",
  ui_story_5088_50880202_26_dialog_content = "The Elder Council was forced into rebellion, and the flames of war still burned throughout the kingdom! Is this what you call \"peace\"?!",
  ui_story_5088_50880202_27_dialog_content = "The flames are under my control. I know exactly what they must burn.",
  ui_story_5088_50880202_28_dialog_content = "...!",
  ui_story_5088_50880202_29_dialog_content = "Who was your spy within the Elder Council?",
  ui_story_5088_50880202_30_dialog_content = "And who have you sent to destroy them?",
  ui_story_5088_50880202_31_dialog_content = "Why was I left in the dark all this time?!",
  ui_story_5088_50880202_32_dialog_content = "Achilles, when you swore to uphold justice at all costs...",
  ui_story_5088_50880202_33_dialog_content = "I knew I had to distance myself from you.",
  ui_story_5088_50880202_34_dialog_content = "But there are still so many people in the Elder Council who are loyal to the kingdom... How could you...",
  ui_story_5088_50880202_35_dialog_content = "Think, Achilles.",
  ui_story_5088_50880202_36_dialog_content = "The north was once a chaotic and war-stricken place, but you and I have laid the foundations for peace.",
  ui_story_5088_50880202_37_dialog_content = "No one in the Elder Council cherishes peace, which is why they chose to sow animosity between us.",
  ui_story_5088_50880202_38_dialog_content = "When my family came under suspicion, that tyrant exiled them to the coldest reaches of the land and left them to die.",
  ui_story_5088_50880202_39_dialog_content = "The Elder Council bore witness to the destruction of my family, and did nothing to help me as I was taken prisoner.",
  ui_story_5088_50880202_40_dialog_content = "I have accepted everything that has happened to me.",
  ui_story_5088_50880202_41_dialog_content = "So you decided to exterminate the former king's entire family.",
  ui_story_5088_50880202_42_dialog_content = "At the time... I was too late to stop you.",
  ui_story_5088_50880202_43_dialog_content = "But even then, I didn't realize your hatred extended toward the Elder Council as well...",
  ui_story_5088_50880202_44_dialog_content = "You're wrong. I let go of my grudge long ago, which is why we were able to unite the warring city-states of Northland into one true nation.",
  ui_story_5088_50880202_45_dialog_content = "What has the Elder Council done to deserve their fate?",
  ui_story_5088_50880202_46_dialog_content = "They fear me, Achilles. They wish to stop my revolution by turning our people against me, including the priests.",
  ui_story_5088_50880202_47_dialog_content = "They've also wronged you in order to win your favor and your military strength, haven't they?",
  ui_story_5088_50880202_48_dialog_content = "That's none of my concern.",
  ui_story_5088_50880202_49_dialog_content = "There was once a time when I believed either of us could be king. But you have always been too upright for the throne.",
  ui_story_5088_50880202_50_dialog_content = "Someone like you could never purge the corruption from our kingdom and bring peace to its people.",
  ui_story_5088_50880202_51_dialog_content = "If only you were born into an era of peace. As powerful and impartial as you are, you could've been the greatest marshal in our kingdom's history.",
  ui_story_5088_50880202_52_dialog_content = "But right now, there's nothing you can do to help me. You are hardly the marshal Northland needs at this time.",
  ui_story_5088_50880202_53_dialog_content = "Which is why you can never be more than a general... Or a monster in charge of other monsters.",
  ui_story_5088_50880202_54_dialog_content = "Enough of your senseless prattling, Agamemnon! Release my comrades and stop all of this senseless killing.",
  ui_story_5088_50880202_55_dialog_content = "And if I refuse?",
  ui_story_5088_50880202_56_dialog_content = "The source of the Eclipsite menace has been eradicated, the Elder Council is on the brink of collapse, and the temple has lost its High Priest.",
  ui_story_5088_50880202_57_dialog_content = "As the undeniable victor, why do you insist on continuing your murderous spree?",
  ui_story_5088_50880202_58_dialog_content = "Now that you've eliminated two of the three governing bodies of our kingdom, you could become emperor of all Northland.",
  ui_story_5088_50880202_59_dialog_content = "You and your compatriots are far too powerful to be left alive. Your very existences pose a great risk to the peace I so desperately desire.",
  ui_story_5088_50880202_60_dialog_content = "And the fact remains that you are all powerless to suppress the corruption in your bodies.",
  ui_story_5088_50880202_61_dialog_content = "At the very least... You must spare the children and let my comrades leave the kingdom... So that they can take our dear friend back to her distant homeland and lay her to rest.",
  ui_story_5088_50880202_62_dialog_content = "I will stay here, and pay whatever price you ask of me.",
  ui_story_5088_50880202_63_dialog_content = "I never thought you would speak on behalf of the Elder Council at the very end. Are you doing this out of justice? Or perhaps out of allegiance to your own people?",
  ui_story_5088_50880202_64_dialog_content = "I'm doing this as a person, Agamemnon.",
  ui_story_5088_50880202_65_dialog_content = "... The other Star Warriors have fallen into madness. You, Achilles, are the only one whose will hasn't faltered.",
  ui_story_5088_50880202_66_dialog_content = "It's no wonder that foolish Caelestite gave her life to—",
  ui_story_5088_50880202_67_dialog_content = "<color=#e8d9bb>The pressure from a powerful slash cuts him off mid-sentence.</color>",
  ui_story_5088_50880202_68_dialog_content = "Not another word!",
  ui_story_5088_50880202_69_dialog_content = "I won't let you insult my friend any longer!",
  ui_story_5088_50880202_70_dialog_content = "... \"Friend,\" you say?",
  ui_story_5088_50880202_71_dialog_content = "Was I not your friend as well, Achilles?",
  ui_story_5088_50880202_72_dialog_content = "During our military days, you were my most dependable ally, as trustworthy as my own sword arm. I still remember the countless times you saved my life.",
  ui_story_5088_50880202_73_dialog_content = "But the most memorable instance... was when I dropped my shield in battle, and you protected me with your body. I remember all seventeen of the injuries you sustained that day.",
  ui_story_5088_50880202_74_dialog_content = "... And because of me, you broke ranks and cut down the spearmen who were closing in on me, all without your shield.",
  ui_story_5088_50880202_75_dialog_content = "Your wounds were just as grave as mine, and you were put in shackles for violating orders. Your own sister passed away in prison because of it too.",
  ui_story_5088_50880202_76_dialog_content = "Allies...",
  ui_story_5088_50880202_77_dialog_content = "I know you can never kill me, Achilles, because there isn't a better person alive who could take my place.",
  ui_story_5088_50880202_78_dialog_content = "Neither of us wants to plunge our kingdom into chaos once again.",
  ui_story_5088_50880202_79_dialog_content = "...",
  ui_story_5088_50880202_80_dialog_content = "Now leave.",
  ui_story_5088_50880202_81_dialog_content = "?!",
  ui_story_5088_50880202_82_dialog_content = "It makes no difference if I let one of you or all of you go.",
  ui_story_5088_50880202_83_dialog_content = "Take them all with you. Your teammates, the warriors who swear their loyalty to you, the children of the Elder Council, and your Caelestite friend...",
  ui_story_5088_50880202_84_dialog_content = "Take them someplace far away, and never set foot on our pure and untainted lands ever again.",
  ui_story_5088_50880202_85_dialog_content = "I'll remove any mention of you and your comrades from the annals of our history. No one will sing your praises or seek the power you possess ever again.",
  ui_story_5088_50880202_86_dialog_content = "I'll ensure that the art of creating Eclipsite soldiers is lost to the passage of time.",
  ui_story_5088_50880202_87_dialog_content = "Look me in the eyes, Gaius Agamemnon, and tell me that you're doing this not for personal gain, but for the sake of our ideals.",
  ui_story_5088_50880202_88_dialog_content = "Yes. Even as I descend into a river of unforgivable sin... I will always yearn for peace. This will be especially true once I take the throne and look upon the chaos as king.",
  ui_story_5088_50880202_89_dialog_content = "And so, I will bear the filth which you could never accept. So long as Northland is plagued by neither war nor the ones who seek it, I solemnly swear—",
  ui_story_5088_50880202_90_dialog_content = "No boy will have to beg for bread to survive. No saintess will have to burn ever again. No child will ever get lost in the forest...",
  ui_story_5088_50880202_91_dialog_content = "No girl will be feared because of her flames. No child will be born and left in an orphanage. No one will have to spend their entire life in tears...",
  ui_story_5088_50880202_92_dialog_content = "And no upright person will have to feel the pain of betrayal ever again.",
  ui_story_5088_50880202_93_dialog_content = "I will devour every trace of filth until all of Northland is as pure and flawless as the snow that covers it.",
  ui_story_5088_50880202_94_dialog_content = "For this, I will pay any price.",
  ui_story_5088_50880202_95_dialog_content = "Tell me, how does it feel to sit alone atop a rotten throne?",
  ui_story_5088_50880202_96_dialog_content = "...",
  ui_story_5088_50880202_97_dialog_content = "...",
  ui_story_5088_50880202_98_dialog_content = "Farewell, Gaius Agamemnon.",
  ui_story_5088_50880202_99_dialog_content = "Farewell, my friend.",
  ui_story_5088_50880202_100_dialog_content = "May you all find peace one day.",
  ui_story_5088_50880202_101_dialog_content = "... It's cold.",
  ui_story_5088_50880202_102_dialog_content = "This throne is colder than you could ever imagine, my friend.",
  ui_story_5088_50880202_103_dialog_content = "<color=#e8d9bb>Day Six: The Hunters—A Tale Lost to Time.</color>",
  ui_story_5088_50880202_104_dialog_content = "Truth is often buried beneath the sands of time.",
  ui_story_5088_50880202_105_dialog_content = "What else can I do? Even if I record everything... Will anyone ever know the truth?",
  ui_story_5088_50880202_106_dialog_content = "I have failed. There's nothing I can do to save you.",
  ui_story_5088_50880202_107_dialog_content = "But I have also succeeded. No one in the kingdom will ever mention your names again.",
  ui_story_5088_50880202_108_dialog_content = "You will be forgotten. Regardless of achievement or disgrace, you will be forgotten.",
  ui_story_5088_50880202_109_dialog_content = "You are all fading stars. Once your light dims, no one will remember you.",
  ui_story_5088_50880202_110_dialog_content = "And yet you're still writing in your journal, Lord Achilles.",
  ui_story_5088_50880202_111_dialog_content = "Even if we destroy every record of their existence, you can never forget about them.",
  ui_story_5088_50880202_112_dialog_content = "It's because Freya once said that she didn't want us to be forgotten.",
  ui_story_5088_50880202_113_dialog_content = "The rest of the world can forget about us, since that calamity will never appear in this world again.",
  ui_story_5088_50880202_114_dialog_content = "But I can't... I can't forget about them...",
  ui_story_5088_50880202_115_dialog_content = "The words I'm writing are only for myself.",
  ui_story_5088_50880202_116_dialog_content = "... And you're certain this seal is sturdy enough to withstand the test of time?",
  ui_story_5088_50880202_117_dialog_content = "Everything is in place now. The seal will only be broken once a Caelestite decides to free them from this place.",
  ui_story_5088_50880202_118_dialog_content = "The stars are at peace now, and the children have been safely escorted out of Northland by the others...",
  ui_story_5088_50880202_119_dialog_content = "There's only one last thing I can do for you, Lord Achilles, and now is the time to do it.",
  ui_story_5088_50880202_120_dialog_content = "What would that be?",
  ui_story_5088_50880202_121_dialog_content = "I'm the only mortal in this world who knows about this place, and I have to ensure that its existence remains a secret forever.",
  ui_story_5088_50880202_122_dialog_content = "I owe you my life, my lord, and now it's time for me to repay you with it!",
  ui_story_5088_50880202_123_dialog_content = "Lord Achilles? Why did you stop me?",
  ui_story_5088_50880202_124_dialog_content = "That's enough, Anthony. You've already given me your loyalty and friendship. There's no need to give me your life.",
  ui_story_5088_50880202_125_dialog_content = "But...",
  ui_story_5088_50880202_126_dialog_content = "This formation serves two purposes: to maintain the seal on my comrades, and to prevent me from harming them once I lose my sanity.",
  ui_story_5088_50880202_127_dialog_content = "In exchange, it will trap me here and slowly drain my strength. But even if I become an Eclipsite, I'll continue to watch over them.",
  ui_story_5088_50880202_128_dialog_content = "I have no way of leaving this place, Anthony.",
  ui_story_5088_50880202_129_dialog_content = "So please, find Eraveil in my place and help me lay Ludweiss to rest in her homeland.",
  ui_story_5088_50880202_130_dialog_content = "This was the promise I made to her.",
  ui_story_5088_50880202_131_dialog_content = "Ludweiss once told me that Eraveil was not yet open to the outside world. It may take you years to find it.",
  ui_story_5088_50880202_132_dialog_content = "But until then, you're not allowed to die.",
  ui_story_5088_50880202_133_dialog_content = "Lord Achilles... You knew I would try to take my life in order to keep this place a secret, didn't you?",
  ui_story_5088_50880202_134_dialog_content = "...",
  ui_story_5088_50880202_135_dialog_content = "So you decided to use this as an excuse to keep me from doing so.",
  ui_story_5088_50880202_136_dialog_content = "You've given every ounce of kindness in your body to everyone but yourself. It isn't fair, my lord.",
  ui_story_5088_50880202_137_dialog_content = "But if this is your will... Then, I, Anthony Longinus, hereby swear to you:",
  ui_story_5088_50880202_138_dialog_content = "The Longinus family will search for Eraveil, as well as the means to save you and your comrades. Even if our search spans across generations, we will not stop until we succeed.",
  ui_story_5088_50880202_139_dialog_content = "Anthony...",
  ui_story_5088_50880202_140_dialog_content = "From this day forth, my descendants and I will bear your secret.",
  ui_story_5088_50880202_141_dialog_content = "And if I'm unable to be with you at the end of your eternal vigil, Lord Achilles...",
  ui_story_5088_50880202_142_dialog_content = "The Longinus family will stay by your side throughout the ages.",
  ui_story_5088_50880202_143_dialog_content = "There's no need for that.",
  ui_story_5088_50880202_144_dialog_content = "The world may forget about the stars, but we will always persist in our quest to save you. If we have to do so in total obscurity, then so be it.",
  ui_story_5088_50880202_145_dialog_content = "You and the others deserve it.",
  ui_story_5088_50880202_146_dialog_content = "...",
  ui_story_5088_50880202_147_dialog_content = "<color=#e8d9bb>Shortly after Anthony leaves, Claymore uses a simple set of tools to carve out a number of new emblems.</color>",
  ui_story_5088_50880202_148_dialog_content = "<color=#e8d9bb>After carefully carving the image of a scroll onto one of them, he carefully places it inside his notebook.</color>",
  ui_story_5088_50880202_149_dialog_content = "Ludweiss, let's wait for the melting of the snow and the coming of spring together.",
  ui_story_5088_50880301_1_dialog_content = "So this emblem was made for Miss Ludweiss...",
  ui_story_5088_50880301_2_dialog_content = "And just like in Adras' dream, Claymore, or rather Achilles, used to be a kind and upright person.",
  ui_story_5088_50880301_3_dialog_content = "But the Claymore we just saw was such a violent being. What could've happened between back then and now?",
  ui_story_5088_50880301_4_dialog_content = "(Not only that... Adras and his comrades were the ones who killed their captain with their own hands.)",
  ui_story_5088_50880301_5_dialog_content = "Are you alright?",
  ui_story_5088_50880301_6_dialog_content = "Ever since that day, you've had such a concerned look on your face.",
  ui_story_5088_50880301_7_dialog_content = "Is something about my dream bothering you?",
  ui_story_5088_50880301_8_dialog_content = "If it is, it's always a good idea to tell other people about it. Don't bottle everything up, okay?",
  ui_story_5088_50880301_9_dialog_content = "Do you guys still remember when we went back to that frozen cave?",
  ui_story_5088_50880301_10_dialog_content = "You were all so familiar with that place...",
  ui_story_5088_50880301_11_dialog_content = "That's because we went there on a mission a long, long time ago.",
  ui_story_5088_50880301_12_dialog_content = "We can't remember any specific details, though. It might be a side-effect of being sealed away for so long...",
  ui_story_5088_50880301_13_dialog_content = "But what I do remember is that there was something clearly wrong with that man during our mission...",
  ui_story_5088_50880301_14_dialog_content = "Ugh... It's no good, I can't remember anything else... But many years later, that was where you found us...",
  ui_story_5088_50880301_15_dialog_content = "It proves that he betrayed us.",
  ui_story_5088_50880301_16_dialog_content = "But when we woke up, the place was totally different from when we first entered it.",
  ui_story_5088_50880301_17_dialog_content = "I guess two thousand years can really change a place, right?",
  ui_story_5088_50880301_18_dialog_content = "I... I only went to that cave under Queen Bethlehem's guidance.",
  ui_story_5088_50880301_19_dialog_content = "A while ago, I rescued an Aurorian that had been frozen in the ice. From the very beginning, I thought...",
  ui_story_5088_50880301_20_dialog_content = "Bethlehem...?",
  ui_story_5088_50880301_21_dialog_content = "... Huh?",
  ui_story_5088_50880301_22_dialog_content = "(I'm all out of clues. What should I do now?)",
  ui_story_5088_50880301_23_dialog_content = "(If I combine everything I saw just now with what I saw in the dream, it proves that Claymore was the one who sealed everyone away in the arena before taking them to the frozen cave.)",
  ui_story_5088_50880301_24_dialog_content = "(But when they finally woke up, their memories were in total disarray, and they ended up killing Claymore without even realizing it...)",
  ui_story_5088_50880301_25_dialog_content = "(If this is really the truth... It's almost too painful to bear...)",
  ui_story_5088_50880301_26_dialog_content = "I'm sorry, but there's someplace I want to go.",
  ui_story_5088_50880301_27_dialog_content = "Haven't I already told you enough times, my dear? It's impossible for me to know the full history of each of these objects.",
  ui_story_5088_50880301_28_dialog_content = "Not to mention that many of these things are ill-gotten gains from the senior Istvan's early days.",
  ui_story_5088_50880301_29_dialog_content = "Back then, Umbraton was a cesspool of crime and chaos. Just about everything in the town came from dubious origins at best.",
  ui_story_5088_50880301_30_dialog_content = "I was the only one who was willing to safeguard these objects, as well.",
  ui_story_5088_50880301_31_dialog_content = "But this is really important to me...",
  ui_story_5088_50880301_32_dialog_content = "Oh don't frown like that, my dear! It breaks my heart to see you so dejected! Ah, if only Vergil were here to sort things out.",
  ui_story_5088_50880301_33_dialog_content = "How about this?",
  ui_story_5088_50880301_34_dialog_content = "It's getting late, so why don't I just sell you every single scroll and handwritten note in here all at once?",
  ui_story_5088_50880301_35_dialog_content = "That way, you can take it all home and research it at your own pace. I'll even throw in a family discount, just for you! So what do you say?",
  ui_story_5088_50880301_36_dialog_content = "O-Okay then...",
  ui_story_5088_50880301_37_dialog_content = "Hey Caelestite... You sure you want to walk around Umbraton all by yourself this late at night?",
  ui_story_5088_50880301_38_dialog_content = "Hey, see that? The Caelestite just bought a ton of stuff from the Cloudrover Guild.",
  ui_story_5088_50880301_39_dialog_content = "I dunno. Robbing the last Caelestite could have some pretty serious consequences. Do you have any idea how scary the Lovegators can be?",
  ui_story_5088_50880301_40_dialog_content = "C'mon, it's the middle of the night! We just have to rough him up a little and run off with the goods before anyone notices!",
  ui_story_5088_50880301_41_dialog_content = "We could skip town and go somewhere far away, a place where even the Shadowlord couldn't find us.",
  ui_story_5088_50880301_42_dialog_content = "Just look at the size of that case! Once we make our escape, we can live like kings for the rest of our lives!",
  ui_story_5088_50880301_43_dialog_content = "... Fine, but let's wait until he makes it a little further out of Umbraton. That's when we'll make our move.",
  ui_story_5088_50880301_44_dialog_content = "Who's there?!",
  ui_story_5088_50880301_45_dialog_content = "Oh? Guess it's true that the Caelestite can sense us.",
  ui_story_5088_50880301_46_dialog_content = "If that's the case, we'll have to make our move now!",
  ui_story_5088_50880301_47_dialog_content = "W-Wait a minute! You don't want any of this stuff! It's just a bunch of old writings and scrolls!",
  ui_story_5088_50880301_48_dialog_content = "Hear that? Sounds like a historical treasure to me!",
  ui_story_5088_50880301_49_dialog_content = "(They're not listening to me at all!)",
  ui_story_5088_50880301_50_dialog_content = "Get going, idiots.",
  ui_story_5088_50880301_51_dialog_content = "Huh?",
  ui_story_5088_50880301_52_dialog_content = "I-It's her! The Raven Hunter!",
  ui_story_5088_50880301_53_dialog_content = "What's she doing here?!",
  ui_story_5088_50880301_54_dialog_content = "Alright, you shameless lowlifes... Time to face your punishment!",
  ui_story_5088_50880302_1_dialog_content = "Uh... Thanks.",
  ui_story_5088_50880302_2_dialog_content = "You idiot!",
  ui_story_5088_50880302_3_dialog_content = "Huh?",
  ui_story_5088_50880302_4_dialog_content = "You know full well you're a Caelestite, so why do you insist on walking around completely unprotected?",
  ui_story_5088_50880302_5_dialog_content = "Even if you're on good terms with the Shadowlord and his gang, that's no excuse for underestimating the dangers of Umbraton.",
  ui_story_5088_50880302_6_dialog_content = "Don't let me catch you walking through these streets alone ever again.",
  ui_story_5088_50880302_7_dialog_content = "Unbelievable. You actually got yourself mugged.",
  ui_story_5088_50880302_8_dialog_content = "All of Umbraton is abuzz right now because of you.",
  ui_story_5088_50880302_9_dialog_content = "When I saw that you were perfectly fine, I thought there had been some mistake.",
  ui_story_5088_50880302_10_dialog_content = "Huh?",
  ui_story_5088_50880302_11_dialog_content = "The Shadowlord and his people were furious when they found out, so they hunted down the guys who tried to rob you.",
  ui_story_5088_50880302_12_dialog_content = "But since you're okay, I suppose it was a good opportunity to take out some more of the trash around here.",
  ui_story_5088_50880302_13_dialog_content = "Here, a token of sympathy from Lady Sheol. She was very insistent that I give this to you.",
  ui_story_5088_50880302_14_dialog_content = "Thanks... But really, I'm fine. Someone came to my rescue just in the nick of time.",
  ui_story_5088_50880302_15_dialog_content = "I heard. The scumbags who mugged you told us that the Raven Hunter was the one who saved you.",
  ui_story_5088_50880302_16_dialog_content = "Yeah, that's what they called her too... The Raven Hunter...",
  ui_story_5088_50880302_17_dialog_content = "She started showing up around two years ago. Every now and then, she hunts down criminals in the dead of night and punishes them.",
  ui_story_5088_50880302_18_dialog_content = "An Umbraton vigilante who only appears at night? Sounds a lot like Pittman from back in the day.",
  ui_story_5088_50880302_19_dialog_content = "Be careful of what you say. That person's methods are far more brutal.",
  ui_story_5088_50880302_20_dialog_content = "We're both ravens, but one thing we don't have in common is that she doesn't leave any loose ends behind.",
  ui_story_5088_50880302_21_dialog_content = "Regardless of their crimes, she beats them all to within an inch of their lives.",
  ui_story_5088_50880302_22_dialog_content = "A lot of people suspect that she might be a rogue Justice Knight or something.",
  ui_story_5088_50880302_23_dialog_content = "Package for you, Mr. Navigator! Pwease sign here.",
  ui_story_5088_50880302_24_dialog_content = "Thank you.",
  ui_story_5088_50880302_25_dialog_content = "You bought even more of this stuff?",
  ui_story_5088_50880302_26_dialog_content = "Aren't you just trying to find a needle in a haystack at this point?",
  ui_story_5088_50880302_27_dialog_content = "I know... But this is all I can do right now... Besides, scouring history for lost knowledge will always be a challenge.",
  ui_story_5088_50880302_28_dialog_content = "...",
  ui_story_5088_50880302_29_dialog_content = "(Huh?)",
  ui_story_5088_50880302_30_dialog_content = "So Tweety, do you have deliveries to make out here too?",
  ui_story_5088_50880302_31_dialog_content = "Such a bad memowy, Mr. Navigator. It's almost Windelion, you know!",
  ui_story_5088_50880302_32_dialog_content = "I came to confirm Ewaveil's mail!",
  ui_story_5088_50880302_33_dialog_content = "Hey, you're right! I forgot all about it!",
  ui_story_5088_50880302_34_dialog_content = "Vice and Carleen should be back before Windelion. I'm sure Vice will be more than happy to...",
  ui_story_5088_50880302_35_dialog_content = "Now that I've delivered Lady Sheol's gift and confirmed your safety, I'm taking my leave.",
  ui_story_5088_50880302_36_dialog_content = "We should get going too! See you awound, Mr. Navigator!",
  ui_story_5088_50880302_37_dialog_content = "... Bye.",
  ui_story_5088_50880302_38_dialog_content = "Alright, see you all later!",
  ui_story_5088_50880302_39_dialog_content = "Wait, Casta—",
  ui_story_5088_50880302_40_dialog_content = "I don't know if I can handle flipping through every single one of these notes.",
  ui_story_5088_50880302_41_dialog_content = "Think you can use your incredible luck to tell me where to start?",
  ui_story_5088_50880302_42_dialog_content = "When hard work can't save you and you have nowhere else to turn, that's when you should clap your hands and pray for luck.",
  ui_story_5088_50880302_43_dialog_content = "But you can't rely on luck when hard work is still an option.",
  ui_story_5088_50880302_44_dialog_content = "Then again, I could add it to my list of services rendered... Here, start with this one.",
  ui_story_5088_50880302_45_dialog_content = "Huh?",
  ui_story_5088_50880302_46_dialog_content = "Looks like your secret technique failed this time. I don't sense anything from this notebook.",
  ui_story_5088_50880302_47_dialog_content = "I rely on a lot more than just my luck, you know.",
  ui_story_5088_50880302_48_dialog_content = "Why don't you try believing in yourself a little more instead?",
  ui_story_5088_50880302_49_dialog_content = "I suppose you're right... Sorry, Casta, I shouldn't have tried to take advantage of your good luck like that.",
  ui_story_5088_50880302_50_dialog_content = "H-Huh?!",
  ui_story_5088_50880302_51_dialog_content = "Look at the cover of this notebook... It's a Windelion Doll!",
  ui_story_5088_50880302_52_dialog_content = "It... It must've belonged to a Caelestite!",
  ui_story_5088_50880302_53_dialog_content = "(It's faint, but this notebook is giving off a wavelength as familiar as those emblems. This may just be Miss Ludweiss' notebook...)",
  ui_story_5088_50880302_54_dialog_content = "Looks like you're on the right track again. See you.",
  ui_story_5088_50880302_55_dialog_content = "(But Miss Ludweiss never returned to Eraveil in her lifetime. Maybe there were other traveling Caelestites like her who knew how to make Windelion Dolls?)",
  ui_story_5088_50880302_56_dialog_content = "Still, there's no denying the familiar feeling coming from this notebook... Guess I won't know until I open it and see...",
  ui_story_5088_50880401_1_dialog_content = "<color=#e8d9bb>In the middle of a cold, winter night, a special group of people gather just outside of a frozen cave.</color>",
  ui_story_5088_50880401_2_dialog_content = "<color=#e8d9bb>From within the cave, their venerable and aging master speaks to them about an existence they must protect.</color>",
  ui_story_5088_50880401_3_dialog_content = "... The king has fulfilled his promise, and peace has been restored. Now, there is no need for the world to remember the Eclipsite Soldiers, or the augmentation techniques which gave rise to them.",
  ui_story_5088_50880401_4_dialog_content = "The children who were exiled from these lands found new tribes to call their own. In fact, some claim that they even discovered a paradise floating in the sky.",
  ui_story_5088_50880401_5_dialog_content = "Lady Freya's kin rebuilt the border city into a splendid and beautiful place. The frozen mountain, which stood since time immemorial, has melted and formed a lake as pristine and glassy as a mirror.",
  ui_story_5088_50880401_6_dialog_content = "*coughs* And yet... I never succeeded in finding Eraveil.",
  ui_story_5088_50880401_7_dialog_content = "Though my life has spanned many years, I failed to take our dear friend Ludweiss back to her home and lay her to rest.",
  ui_story_5088_50880401_8_dialog_content = "... It's not your fault, Anthony.",
  ui_story_5088_50880401_9_dialog_content = "I've grown old, Lord Achilles... Death threatens to take me at any time.",
  ui_story_5088_50880401_10_dialog_content = "But before it does, I have more to say to you. That is why I asked my children to bring me here today.",
  ui_story_5088_50880401_11_dialog_content = "I wish to express my remorse, my lord. By failing to complete the mission you've given me, I have failed you as your guard... And though I'm your soldier, I have no way of dying at your side in battle.",
  ui_story_5088_50880401_12_dialog_content = "I believed myself to be loyal, and yet I've done nothing but disappoint you... and even at the end, I'll have to close my eyes before you.",
  ui_story_5088_50880401_13_dialog_content = "Raise your head, Anthony. I don't blame you, only the utmost pride and gratitude.",
  ui_story_5088_50880401_14_dialog_content = "You've already done more than enough for us, my friend.",
  ui_story_5088_50880401_15_dialog_content = "No... You deserve far better than this, my lord! You've already lost so many people... You must think I'm cruel for letting you see me in my old and dying state.",
  ui_story_5088_50880401_16_dialog_content = "But I worried that if I didn't come, you would concern yourself unnecessarily for my sake.",
  ui_story_5088_50880401_17_dialog_content = "As your guard... It's only right that I die before you. If I didn't know about your immense burden, I would dream of fighting at your side again someday.",
  ui_story_5088_50880401_18_dialog_content = "My general, the hero of the kingdom... You devoured the darkness, yet I am the only one who bore witness to your light.",
  ui_story_5088_50880401_19_dialog_content = "My descendants will be the ones to stay at your side from now on... But few will ever remember the greatness of your accomplishments.",
  ui_story_5088_50880401_20_dialog_content = "Rest assured, Anthony.",
  ui_story_5088_50880401_21_dialog_content = "Even if history forgets us, I will never abandon my purpose. I made a promise to my comrades that I would bear it all.",
  ui_story_5088_50880401_22_dialog_content = "So let go of your remorse and rest, my weary friend. You've more than earned it.",
  ui_story_5088_50880401_23_dialog_content = "Ah... Your forgiveness means more to me than you'll ever know, my lord.",
  ui_story_5088_50880401_24_dialog_content = "But what about Ludweiss? I can't close my eyes just yet. I can't...",
  ui_story_5088_50880401_25_dialog_content = "You saved me and yet I failed you, Lord Achilles. I failed Dominic as well.",
  ui_story_5088_50880401_26_dialog_content = "Look back on your life, Anthony.",
  ui_story_5088_50880401_27_dialog_content = "You have always protected the weak and defenseless, as well as our honor. You have sown the seeds of love and loyalty, and raised your children and grandchildren with pride.",
  ui_story_5088_50880401_28_dialog_content = "You sacrificed wealth and glory for the sake of keeping your promise. No soul shines brighter than yours, my friend.",
  ui_story_5088_50880401_29_dialog_content = "No part of your life was spent in vain. You have honored the wishes of those who sacrificed themselves... And my own wish as well.",
  ui_story_5088_50880401_30_dialog_content = "But...",
  ui_story_5088_50880401_31_dialog_content = "Be at peace, Anthony. You have earned your place in the paradise of soldiers.",
  ui_story_5088_50880401_32_dialog_content = "And if it should close its doors to you, I'll be there to pry them open with my blade.",
  ui_story_5088_50880401_33_dialog_content = "So don't worry... Ludweiss and I will linger in this world, waiting for the dawn of the future she once saw.",
  ui_story_5088_50880401_34_dialog_content = "So let your final moments be filled with hope, my friend.",
  ui_story_5088_50880401_35_dialog_content = "Lord Achilles...",
  ui_story_5088_50880401_36_dialog_content = "You want to know why I'm going this far for them?",
  ui_story_5088_50880401_37_dialog_content = "You're doing the same, aren't you? As far as I'm concerned, there's no difference between us.",
  ui_story_5088_50880401_38_dialog_content = "As Lord Achilles' faithful guard, I have a duty to uphold.",
  ui_story_5088_50880401_39_dialog_content = "But I'm not certain if things can truly change...",
  ui_story_5088_50880401_40_dialog_content = "Hey, Anthony... If you ask me, that's exactly what hope is: a torch that burns in the darkest night.",
  ui_story_5088_50880401_41_dialog_content = "I know I'll be burned out...",
  ui_story_5088_50880401_42_dialog_content = "But the path I've forged will guide others out of the darkness.",
  ui_story_5088_50880401_43_dialog_content = "From now on, those who follow this path need no longer fear getting lost.",
  ui_story_5088_50880401_44_dialog_content = "The stars shine down on all of us. You, me, and countless other people who suffer in our world.",
  ui_story_5088_50880401_45_dialog_content = "Do you really think they could see the silver lining before they started?",
  ui_story_5088_50880401_46_dialog_content = "You're saying...",
  ui_story_5088_50880401_47_dialog_content = "Look behind you, Anthony.",
  ui_story_5088_50880401_48_dialog_content = "You've already illuminated the way for so many people.",
  ui_story_5088_50880401_49_dialog_content = "It may not be now, but that change will definitely happen sometime in the future, and it's all thanks to what you've done in life.",
  ui_story_5088_50880401_50_dialog_content = "Have faith in the future. You've done so much for everyone else, but now it's your turn to rest.",
  ui_story_5088_50880401_51_dialog_content = "Do I... truly deserve this?",
  ui_story_5088_50880401_52_dialog_content = "Heh, do you really have to ask?",
  ui_story_5088_50880401_53_dialog_content = "Anthony Longinus... I am honored to have witnessed the moment in which the flame of your proud and noble soul was extinguished. Be well as you journey to the soldier's paradise, my friend.",
  ui_story_5088_50880401_54_dialog_content = "You deserve it all.",
  ui_story_5088_50880401_55_dialog_content = "Grandfather smiled as he passed away.",
  ui_story_5088_50880401_56_dialog_content = "...",
  ui_story_5088_50880401_57_dialog_content = "As his successor, I am honored to enter this cave and serve you, Lord Achilles.",
  ui_story_5088_50880401_58_dialog_content = "Then, take this emblem and wear it with pride.",
  ui_story_5088_50880401_59_dialog_content = "I present it to him and to you, his noble descendants.",
  ui_story_5088_50880401_60_dialog_content = "B-But my lord, this emblem... It's far too precious for us to accept.",
  ui_story_5088_50880401_61_dialog_content = "Anthony was my comrade-in-arms, as well as a true friend. He earned my respect, and so I extend the same to you.",
  ui_story_5088_50880401_62_dialog_content = "I only hope that the power of this emblem will be of use to your family.",
  ui_story_5088_50880401_63_dialog_content = "Take him home. Your grandfather lived a full and meaningful life, and deserves to be laid to rest with the tears and blessings of his family.",
  ui_story_5088_50880401_64_dialog_content = "I-I understand, Lord Achilles. If you'll excuse us...",
  ui_story_5088_50880401_65_dialog_content = "My friends... I'd like to rest my eyes for a while too...",
  ui_story_5088_50880401_66_dialog_content = "...",
  ui_story_5088_50880401_67_dialog_content = "Please... Visit me in my dreams and keep me company once again.",
  ui_story_5088_50880401_68_dialog_content = "<color=#e8d9bb>And so began his solitary and endless dream.</color>",
  ui_story_5088_50880401_69_dialog_content = "<color=#e8d9bb>But he will stray from his world once more when he stirs from his slumber.</color>",
  ui_story_5088_50880401_70_dialog_content = "Pardon me... But do you know how to enter Eraveil?",
  ui_story_5088_50880401_71_dialog_content = "We'd been searching for the place for years and were told that the entrance was nearby.",
  ui_story_5088_50880401_72_dialog_content = "Huh? Why are you going to Eraveil?",
  ui_story_5088_50880401_73_dialog_content = "... We have a promise to keep.",
  ui_story_5088_50880401_74_dialog_content = "Forgive me for being blunt, but you greatly resemble the Caelestite mentioned in our family's legends.",
  ui_story_5088_50880401_75_dialog_content = "Oh, is that so? Well, you're lucky because I happen to be...",
  ui_story_5088_50880401_76_dialog_content = "<color=#FFB400>Force Boost!</color>",
  ui_story_5088_50880401_77_dialog_content = "Alright you strange outsiders, let's see what kind of wicked thoughts you have in your heads...",
  ui_story_5088_50880401_78_dialog_content = "You're awake, Lord Achilles!",
  ui_story_5088_50880401_79_dialog_content = "Are you... Anthony's grandson?",
  ui_story_5088_50880401_80_dialog_content = "No, my lord. It's been many, many ages since our ancestor's time.",
  ui_story_5088_50880401_81_dialog_content = "?!",
  ui_story_5088_50880401_82_dialog_content = "My memories have been broken again... How many of them did I lose this time?",
  ui_story_5088_50880401_83_dialog_content = "... Please don't be sad, Lord Achilles.",
  ui_story_5088_50880401_84_dialog_content = "We've come bearing good news.",
  ui_story_5088_50880401_85_dialog_content = "Oh... They were telling the truth after all.",
  ui_story_5088_50880401_86_dialog_content = "So you're Claymore, huh?",
  ui_story_5088_50880401_87_dialog_content = "I must ask that you address Lord Achilles in a more proper way, Mr. Czerny.",
  ui_story_5088_50880401_88_dialog_content = "Seriously? Because I think Claymore sounds way cooler.",
  ui_story_5088_50880401_89_dialog_content = "Are... Are you...?",
  ui_story_5088_50880401_90_dialog_content = "Your clothes... your face...",
  ui_story_5088_50880401_91_dialog_content = "Are you one of Ludweiss' people?",
  ui_story_5088_50880401_92_dialog_content = "Sorry, but I don't know any Ludweiss. Our people aren't exactly fond of running around in the outside world, you know?",
  ui_story_5088_50880401_93_dialog_content = "She once said... Her family left Eraveil long ago, so she spent her entire life searching for it again.",
  ui_story_5088_50880401_94_dialog_content = "Could you two... tell me your names?",
  ui_story_5088_50880401_95_dialog_content = "I will do my best to remember.",
  ui_story_5088_50880401_96_dialog_content = "I would be honored, my lord... I am Dominic Longinus, and I reside on an island currently known as Azurite.",
  ui_story_5088_50880401_97_dialog_content = "Dominic... Hearing that name fills me with nostalgia.",
  ui_story_5088_50880401_98_dialog_content = "Mr. Anthony wished that, in any age, a familiar presence would be there to greet you upon your awakening.",
  ui_story_5088_50880401_99_dialog_content = "Sorry if I sounded rude just now. My name's Czerny, and I found your friend here wandering around Eraveil, so I took a little peek into his mind.",
  ui_story_5088_50880401_100_dialog_content = "I saw your entire story, and I gotta say... It was awesome!",
  ui_story_5088_50880401_101_dialog_content = "Especially your friendship with that Caelestite girl! The whole thing shook me to my core!",
  ui_story_5088_50880401_102_dialog_content = "So, not only am I gonna take Ludweiss back to Eraveil to be laid to rest, I'm also gonna save all of you!",
  ui_story_5088_50880401_103_dialog_content = "Now, where's that seal? Can any Caelestite undo it?",
  ui_story_5088_50880401_104_dialog_content = "... Please don't release them now, Anthony.",
  ui_story_5088_50880401_105_dialog_content = "It's not their time yet.",
  ui_story_5088_50880401_106_dialog_content = "Huh?",
  ui_story_5088_50880401_107_dialog_content = "... Ludweiss sealed them away in order to prevent the corruption in their bodies from spreading to their minds.",
  ui_story_5088_50880401_108_dialog_content = "She wanted to give them a much-needed respite from their suffering.",
  ui_story_5088_50880401_109_dialog_content = "Only when their bodies have been completely transformed will there be hope of preserving their sentience.",
  ui_story_5088_50880401_110_dialog_content = "I have also infused colorless magic into all of their seals. Once their bodies have been released, I want to free their locked emotions as well.",
  ui_story_5088_50880401_111_dialog_content = "I don't really get it... But that's fine. It's your call, after all.",
  ui_story_5088_50880401_112_dialog_content = "You've been fighting off the corruption for a long time now too, haven't you?",
  ui_story_5088_50880401_113_dialog_content = "I'll help you find a way out of this mess... And if that doesn't work, I can seal you away too.",
  ui_story_5088_50880401_114_dialog_content = "Is that truly possible?",
  ui_story_5088_50880401_115_dialog_content = "It can't hurt to try, can it?",
  ui_story_5088_50880401_116_dialog_content = "We can figure out how to save you first, then we can take Ludweiss back and lay her to rest.",
  ui_story_5088_50880401_117_dialog_content = "... I can't be sealed away like the others. If I enter a similar state of unconsciousness, there won't be anyone left to maintain their seal.",
  ui_story_5088_50880401_118_dialog_content = "I appreciate your kind offer, but I have a duty to preserve this formation and ensure that my friends remain sealed away.",
  ui_story_5088_50880401_119_dialog_content = "Ah... That's fine too! We have plenty of time! I'm gonna stick around and try a few things out. Feel free to go home whenever you want, Dominic.",
  ui_story_5088_50880401_120_dialog_content = "If you require anything, Mr. Czerny, all you need to do is ask. Our family is more than willing to assist you.",
  ui_story_5088_50880401_121_dialog_content = "Czerny... Did you really travel here all the way from Eraveil simply because you were moved by our story?",
  ui_story_5088_50880401_122_dialog_content = "Of course! But I also want to prove something to myself.",
  ui_story_5088_50880401_123_dialog_content = "I want to prove... that I'm not a weakling.",
  ui_story_5088_50880401_124_dialog_content = "I want them all to know that I'm capable of accomplishing great things too. When all of this is over, I'm sure everyone will finally respect me as a hero!",
  ui_story_5088_50880401_125_dialog_content = "And then, they'll have no choice but to pick me as a Colossus'... Ah, but that's beside the point.",
  ui_story_5088_50880401_126_dialog_content = "Anyone who rescues a hero can be called a hero too, right?",
  ui_story_5088_50880401_127_dialog_content = "It's good to have an ambition, Czerny. Regardless of your reasons for being here, I'm grateful you came.",
  ui_story_5088_50880401_128_dialog_content = "But a person's greatness doesn't just come from their accomplishments.",
  ui_story_5088_50880401_129_dialog_content = "I hope you remember what you want in the first place.",
  ui_story_5088_50880401_130_dialog_content = "Yeah, of course, I hear you. Just leave it to me!",
  ui_story_5088_50880401_131_dialog_content = "Now then, where should I begin...",
  ui_story_5088_50880401_132_dialog_content = "There's really no need for you to do this, Czerny. Enough people have sacrificed themselves for our sake.",
  ui_story_5088_50880401_133_dialog_content = "So please, just take Ludweiss back to Eraveil.",
  ui_story_5088_50880401_134_dialog_content = "I would be eternally grateful to you for doing that alone.",
  ui_story_5088_50880401_135_dialog_content = "<color=#FFB400>Force Boost!</color>",
  ui_story_5088_50880402_1_dialog_content = "... This is gonna be trickier than I thought.",
  ui_story_5088_50880402_2_dialog_content = "I have no doubt about that.",
  ui_story_5088_50880402_3_dialog_content = "But don't worry, I'll find a way!",
  ui_story_5088_50880402_4_dialog_content = "Besides, you could use the company, don't you think?",
  ui_story_5088_50880402_5_dialog_content = "Dominic can take care of all the food and water I need, so don't worry about me.",
  ui_story_5088_50880402_6_dialog_content = "Haha, this is a new and exciting adventure for me too, you know!",
  ui_story_5088_50880402_7_dialog_content = "... In that case, you can stay with the rest of my comrades.",
  ui_story_5088_50880402_8_dialog_content = "But no matter what you may hear at night, you cannot leave that place. Understand?",
  ui_story_5088_50880402_9_dialog_content = "Oh? This is starting to sound a lot more dangerous now!",
  ui_story_5088_50880402_10_dialog_content = "My light has long been drained. There's no telling how much longer I can hold on.",
  ui_story_5088_50880402_11_dialog_content = "Do you see those markings on the wall? Those were my handiwork.",
  ui_story_5088_50880402_12_dialog_content = "But if you stay close to them, I won't go near you.",
  ui_story_5088_50880402_13_dialog_content = "...",
  ui_story_5088_50880402_14_dialog_content = "Humph, nice try, but you're not scaring me away. Since I already accepted this task, I'm gonna do a good job of it. Just you wait and see!",
  ui_story_5088_50880402_15_dialog_content = "I'm out of clues again... I wonder what happened next? And who's this Czerny guy, anyway?",
  ui_story_5088_50880402_16_dialog_content = "(He doesn't seem very trustworthy. Is this really okay?)",
  ui_story_5088_50880402_17_dialog_content = "Sigh... I should write to Jeriah.",
  ui_story_5088_50880402_18_dialog_content = "(She's an expert on history. Maybe she knows more about the Star Warriors?)",
  ui_story_5088_50880402_19_dialog_content = "What... My nose is bleeding?",
  ui_story_5088_50880402_20_dialog_content = "(Have I been overusing my powers lately?)",
  ui_story_5088_50880402_21_dialog_content = "This isn't good... I can't let anyone see me like this...",
  ui_story_5088_50880402_22_dialog_content = "So this won't work either, huh? Wonder what went wrong this time...",
  ui_story_5088_50880402_23_dialog_content = "I don't mean to blame you, Czerny, but... please stop wasting more time on this.",
  ui_story_5088_50880402_24_dialog_content = "It's not worth the time, you're still young.",
  ui_story_5088_50880402_25_dialog_content = "Not a chance! In fact, that's precisely why I can't give up now!",
  ui_story_5088_50880402_26_dialog_content = "You may not know this, but my people have gotten complacent ever since Eraveil decided to withdraw from the war.",
  ui_story_5088_50880402_27_dialog_content = "To find peace and quiet by retreating from the world... Or so we say. The truth is, we're just hiding away in our own little bubble.",
  ui_story_5088_50880402_28_dialog_content = "But even so, we're still caught up in all kinds of conflict.",
  ui_story_5088_50880402_29_dialog_content = "I'm going to prove to everyone that I can do it. I have what it takes.",
  ui_story_5088_50880402_30_dialog_content = "...",
  ui_story_5088_50880402_31_dialog_content = "I'll get nowhere staying at home. Instead of being stuck on the ground forever, I'd rather take a chance and see how high I can fly.",
  ui_story_5088_50880402_32_dialog_content = "There's still time, so please just trust me! I promise I'll find a way to either seal you away or keep the corruption from taking over your mind.",
  ui_story_5088_50880402_33_dialog_content = "I just need a few days to rest... Just a few will do...",
  ui_story_5088_50880402_34_dialog_content = "... I'm sorry, Czerny, but I'm running out of time.",
  ui_story_5088_50880402_35_dialog_content = "I've already gone through every single one of Ludweiss' journals.",
  ui_story_5088_50880402_36_dialog_content = "But aside from stories and music sheets, nothing can help me.",
  ui_story_5088_50880402_37_dialog_content = "I've been gone for so long... I wonder how many times I could've been chosen as a pilot by now...",
  ui_story_5088_50880402_38_dialog_content = "Damn it!",
  ui_story_5088_50880402_39_dialog_content = "I don't think the music sheets are useless.",
  ui_story_5088_50880402_40_dialog_content = "So you heard, huh? But I'm out here.",
  ui_story_5088_50880402_41_dialog_content = "Czerny, in my cruel and unforgiving world, words of hatred are easily spoken, but few can retain their kindness in the face of pain.",
  ui_story_5088_50880402_42_dialog_content = "That music, which comes from the heart, is a testament to the glory of this world's people.",
  ui_story_5088_50880402_43_dialog_content = "Many years ago, I had the privilege of listening to one of Ludweiss' songs. It was an elegant and compassionate melody, as soft and gentle as moonlight.",
  ui_story_5088_50880402_44_dialog_content = "Could you... enter my dreams and help me recall her music once again?",
  ui_story_5088_50880402_45_dialog_content = "The night is dark and this place is so cold. I think we could both use the calm glow of the moon.",
  ui_story_5088_50880402_46_dialog_content = "... Now that your light's been devoured, the only thing left is the darkness that continues to corrupt you from within.",
  ui_story_5088_50880402_47_dialog_content = "Even as a Caelestite, I can't discern its color. I'm sorry, but your mind is too dangerous for me to enter now.",
  ui_story_5088_50880402_48_dialog_content = "I have no way of safely searching your consciousness for a way to separate you from that darkness. It's the reason why this is taking me so long.",
  ui_story_5088_50880402_49_dialog_content = "But please, just give me a little more time...",
  ui_story_5088_50880402_50_dialog_content = "Alright... After taking a day to rest, I should be able to continue searching through those memories...",
  ui_story_5088_50880402_51_dialog_content = "(I think my hunch is right. Someone deliberately scattered these notes all over Astra.)",
  ui_story_5088_50880402_52_dialog_content = "(Even though the writing is almost completely illegible, the pages are still so full of history. It's almost as if whoever did this couldn't bear to destroy these notes.)",
  ui_story_5088_50880402_53_dialog_content = "(As if... They were waiting for a Caelestite to sense them someday.)",
  ui_story_5088_50880402_54_dialog_content = "... Anyway, it's time to get to work.",
  ui_story_5088_50880402_55_dialog_content = "How could this be happening? I trained for over a decade just to be able to pilot a Colossus.",
  ui_story_5088_50880402_56_dialog_content = "So why am I so useless when it comes to helping Claymore?",
  ui_story_5088_50880402_57_dialog_content = "It shouldn't be like this... It shouldn't...",
  ui_story_5088_50880402_58_dialog_content = "I've been here for so long. I can't possibly go home empty-handed.",
  ui_story_5088_50880402_59_dialog_content = "Czerny...",
  ui_story_5088_50880402_60_dialog_content = "J-Just give me a second to rest. I've been using my psychic powers for so long that it feels like my head's gonna split apart.",
  ui_story_5088_50880402_61_dialog_content = "Run, Czerny.",
  ui_story_5088_50880402_62_dialog_content = "Huh?",
  ui_story_5088_50880402_63_dialog_content = "I couldn't get rid of them—",
  ui_story_5088_50880402_64_dialog_content = "The darkness inside me is rising.",
  ui_story_5088_50880402_65_dialog_content = "You have to go, now! Otherwise...",
  ui_story_5088_50880402_66_dialog_content = "I'm going to kill you!",
  ui_story_5088_50880402_67_dialog_content = "N-No way!",
  ui_story_5088_50880402_68_dialog_content = "Oh, no, he's serious... he won't last much longer.",
  ui_story_5088_50880402_69_dialog_content = "How could this happen? What am I missing here?!",
  ui_story_5088_50880402_70_dialog_content = "That's right, the journals! I need to search through every detail of her mind and find the answer...",
  ui_story_5088_50880402_71_dialog_content = "PlayerName! Wake up! Why are you sleeping on the floor?",
  ui_story_5088_50880402_72_dialog_content = "And look at yourself! You have dried blood running from your nose all the way down to your chest.",
  ui_story_5088_50880402_73_dialog_content = "Just what is it that you're keeping from us? Spill it!",
  ui_story_5088_50880402_74_dialog_content = "I-I'm sorry, but I can't tell you yet!",
  ui_story_5088_50880402_75_dialog_content = "Please, just give me a few more days, and I'll tell you everything. See you!",
  ui_story_5088_50880402_76_dialog_content = "Hey, hold on!",
  ui_story_5088_50880402_77_dialog_content = "(If Claymore isn't saved, I can't let them know about it. Absolutely not...)",
  ui_story_5088_50880402_78_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5088_50880402_79_dialog_content = "No... This can't be possible...",
  ui_story_5088_50880402_80_dialog_content = "She made her <color=#FFB400>choice</color> a long time ago. She even <color=#FFB400>predicted</color> it...",
  ui_story_5088_50880402_81_dialog_content = "The person who's gonna save them isn't me, but another Caelestite in the distant future.",
  ui_story_5088_50880402_82_dialog_content = "<color=#e8d9bb>In the heavy rain, the roar of thunder rips through the sky. Deep within the frozen cave, another roar can be heard...</color>",
  ui_story_5088_50880402_83_dialog_content = "Graaaaaaah—!!!",
  ui_story_5088_50880402_84_dialog_content = "<color=#e8d9bb>With a powerful slash, a wave of pure energy surges out of the cave and tears the ground asunder.</color>",
  ui_story_5088_50880402_85_dialog_content = "<color=#e8d9bb>Though the slash narrowly misses Czerny, his spirit is completely overwhelmed by its murderous intent.</color>",
  ui_story_5088_50880402_86_dialog_content = "<color=#e8d9bb>In that moment, he finally realizes just how dangerous his companion can be.</color>",
  ui_story_5088_50880402_87_dialog_content = "Why... Why does it have to be like this...?",
  ui_story_5088_50880402_88_dialog_content = "<color=#e8d9bb>Trembling violently, Czerny tries to get on his feet, but his legs fail him soon afterward.</color>",
  ui_story_5088_50880402_89_dialog_content = "<color=#e8d9bb>He drops Ludweiss' journals, and the howling storm quickly scatters the pages.</color>",
  ui_story_5088_50880402_90_dialog_content = "No! Noooo—!!!",
  ui_story_5088_50880402_91_dialog_content = "<color=#e8d9bb> Czerny clutches desperately at the pages, but only manages to reclaim a handful of them.</color>",
  ui_story_5088_50880402_92_dialog_content = "<color=#e8d9bb>He has failed.</color>",
  ui_story_5088_50880402_93_dialog_content = "I... I failed them... All of them.",
  ui_story_5088_50880402_94_dialog_content = "I squandered Ludweiss' last-ditch efforts...",
  ui_story_5088_50880402_95_dialog_content = "And I failed Achilles.",
  ui_story_5088_50880402_96_dialog_content = "<color=#e8d9bb>The rain eventually subsides after an unknown length of time, along with the terrible sounds from within the cave.</color>",
  ui_story_5088_50880402_97_dialog_content = "<color=#e8d9bb> Czerny enters the cave once more, clutching what few pages of the notebook he was able to recover.</color>",
  ui_story_5088_50880402_98_dialog_content = "Is there really nothing we can do to help you? Achilles...",
  ui_story_5088_50880402_99_dialog_content = "...",
  ui_story_5088_50880402_100_dialog_content = "I couldn't do anything for you besides waste your time. I never amounted to anything, did I?",
  ui_story_5088_50880402_101_dialog_content = "Tell me, Achilles! Tell me what a fool I am!",
  ui_story_5088_50880402_102_dialog_content = "Leave, Czerny. With my final moments of clarity, I want to thank you for staying with me all this time.",
  ui_story_5088_50880402_103_dialog_content = "Having someone to talk to was enough to placate the monsters in my heart.",
  ui_story_5088_50880402_104_dialog_content = "Leave this place, and tell no one about it... I don't want any more kind-hearted people... to sacrifice anything for my sake.",
  ui_story_5088_50880402_105_dialog_content = "Ahhhhhh—!!!",
  ui_story_5088_50880402_106_dialog_content = "Goodbye... Czerny.",
  ui_story_5088_50880402_107_dialog_content = "You didn't fail, Czerny, I can still help you!",
  ui_story_5088_50880402_108_dialog_content = "No, my voice can't reach him...",
  ui_story_5088_50880402_109_dialog_content = "Argh, why is this happening right now?!",
  ui_story_5088_50880402_110_dialog_content = "Let me help you, Czerny! I can—",
  ui_story_5088_50880402_111_dialog_content = "Wait, don't leave him alone!!!",
  ui_story_5088_50880402_112_dialog_content = "I can still help you!!!",
  ui_story_5088_50880501_1_dialog_content = "You're covered in blood again. Even the Caelestites have a limit to their powers, don't they?",
  ui_story_5088_50880501_2_dialog_content = "Who... are you talking to?",
  ui_story_5088_50880501_3_dialog_content = "Czerny... Where's Czerny?!",
  ui_story_5088_50880501_4_dialog_content = "There's no one else here but us.",
  ui_story_5088_50880501_5_dialog_content = "Wait, who's Czerny?",
  ui_story_5088_50880501_6_dialog_content = "No... No, no! He was just there! He was crying too... I have to help him save Achilles—",
  ui_story_5088_50880501_7_dialog_content = "Out of my way! I'll use my healing magic to—",
  ui_story_5088_50880501_8_dialog_content = "That won't be necessary. I can handle things from here.",
  ui_story_5088_50880501_9_dialog_content = "Urgh...",
  ui_story_5088_50880501_10_dialog_content = "Just look at all this blood! What have you been doing these last few days?!",
  ui_story_5088_50880501_11_dialog_content = "This courier was kind enough to make you some medicine to stop the bleeding. You should thank her for her troubles.",
  ui_story_5088_50880501_12_dialog_content = "Th-Thank you.",
  ui_story_5088_50880501_13_dialog_content = "It's nothing. I just came to pick up your mail.",
  ui_story_5088_50880501_14_dialog_content = "We're not idiots... Whatever it is you're doing, it has something to do with us.",
  ui_story_5088_50880501_15_dialog_content = "And look where you've gotten yourself. If you won't tell us anything, I'll have to tell someone else about your situation, like maybe—",
  ui_story_5088_50880501_16_dialog_content = "Don't tell Vice or Carleen about this! Please!",
  ui_story_5088_50880501_17_dialog_content = "So are you gonna talk?",
  ui_story_5088_50880501_18_dialog_content = "I... I'm trying to learn the truth about something. Sorry... But that's all I can tell you right now.",
  ui_story_5088_50880501_19_dialog_content = "When the time comes, I'll tell you everything.",
  ui_story_5088_50880501_20_dialog_content = "Are you holding back because you're worried about how we'll feel?",
  ui_story_5088_50880501_21_dialog_content = "It's because of my dream that you're caught up in all of this now.",
  ui_story_5088_50880501_22_dialog_content = "I'm sorry... But I have to learn the truth about what happened to Achilles... I mean, Claymore.",
  ui_story_5088_50880501_23_dialog_content = "But I can't reach them after I left your dream...",
  ui_story_5088_50880501_24_dialog_content = "There must be some other way to impart my thoughts... Victoria once said that all Caelestites' thoughts would reach...",
  ui_story_5088_50880501_25_dialog_content = "I... I have to help them...",
  ui_story_5088_50880501_26_dialog_content = "There was a Caelestite at his side. He hasn't given up yet...",
  ui_story_5088_50880501_27_dialog_content = "You look like you barely have any blood left in your body. If you keep pushing yourself like this, you'll die.",
  ui_story_5088_50880501_28_dialog_content = "Why are you going this far for a group of outsiders like us?",
  ui_story_5088_50880501_29_dialog_content = "There are no outsiders on Soroz. You're family.",
  ui_story_5088_50880501_30_dialog_content = "?!",
  ui_story_5088_50880501_31_dialog_content = "Hmm...",
  ui_story_5088_50880501_32_dialog_content = "(And also... I'm just like Czerny. I can't just stand by and do nothing, not after seeing their story.)",
  ui_story_5088_50880501_33_dialog_content = "(I refuse to let these stars fade away so tragically.)",
  ui_story_5088_50880501_34_dialog_content = "Please, I just need a little more time...",
  ui_story_5088_50880501_35_dialog_content = "... Does your head still hurt?",
  ui_story_5088_50880501_36_dialog_content = "I'm fine, I just need some fresh air.",
  ui_story_5088_50880501_37_dialog_content = "I almost forgot, but could you please deliver this to Jeriah? She's stationed at the Rediesel Desert post.",
  ui_story_5088_50880501_38_dialog_content = "... You treat your friends incredibly well. You were looking through those antique books for your friends, weren't you?",
  ui_story_5088_50880501_39_dialog_content = "Forgive me if I'm being intrusive, but this is a letter asking for Lady Jeriah's help, isn't it?",
  ui_story_5088_50880501_40_dialog_content = "Yeah...",
  ui_story_5088_50880501_41_dialog_content = "I want to help them no matter what.",
  ui_story_5088_50880501_42_dialog_content = "I just want to uncover the truth... Even if it's long overdue.",
  ui_story_5088_50880501_43_dialog_content = "(I want to see what happened to Achilles and understand how he ended up like that...)",
  ui_story_5088_50880501_44_dialog_content = "(I still have hope that I can find a way to help him.)",
  ui_story_5088_50880501_45_dialog_content = "(Also, I still need to find Ludweiss' remains.)",
  ui_story_5088_50880501_46_dialog_content = "I'm sorry for giving you such weird answers.",
  ui_story_5088_50880501_47_dialog_content = "Don't be. I'm the one who asked you a strange question to begin with.",
  ui_story_5088_50880501_48_dialog_content = "I'll make sure this letter makes it safely to Lady Jeriah.",
  ui_story_5088_50880501_49_dialog_content = "Thanks for your help, and for the medicine too. It's chilling, but it definitely stopped the bleeding.",
  ui_story_5088_50880501_50_dialog_content = "I'm a courier, and couriers always have a few tricks up their sleeve.",
  ui_story_5088_50880501_51_dialog_content = "Well, I'll be going now.",
  ui_story_5088_50880501_52_dialog_content = "I propose that we end this right here and now.",
  ui_story_5088_50880501_53_dialog_content = "I agree with Friegson. Reclaiming our memories shouldn't come at the expense of yet another life, so let's put a stop to this.",
  ui_story_5088_50880501_54_dialog_content = "Even if it means you'll never remember your love again?",
  ui_story_5088_50880501_55_dialog_content = "... I have all the time in the world to keep searching for her.",
  ui_story_5088_50880501_56_dialog_content = "What do you say, Freya?",
  ui_story_5088_50880501_57_dialog_content = "\"There are no outsiders on Soroz, you're family.\" Those were his words.",
  ui_story_5088_50880501_58_dialog_content = "I've always put my trust in my friends, and he's no different. I respect his decision.",
  ui_story_5088_50880501_59_dialog_content = "You're still hopeful, even though you were betrayed in the past?",
  ui_story_5088_50880501_60_dialog_content = "I'm a knight, leading the charge into battle has always been my duty. A few stab wounds could never discourage me from that.",
  ui_story_5088_50880501_61_dialog_content = "Then I want to believe in him too.",
  ui_story_5088_50880501_62_dialog_content = "We're not perfect by any means, so maybe we shouldn't be so quick to count PlayerName out.",
  ui_story_5088_50880501_63_dialog_content = "In the past, no matter what kind of pain or weakness we faced, as long as we had each other...",
  ui_story_5088_50880501_64_dialog_content = "We could overcome anything and keep pushing forward.",
  ui_story_5088_50880501_65_dialog_content = "Wow... That was beautiful, Cynthia. You haven't said anything that serious in a long time. It's really not like you at all.",
  ui_story_5088_50880501_66_dialog_content = "I want the Silent Hunters to be together again. What does everyone think of that?",
  ui_story_5088_50880501_67_dialog_content = "...",
  ui_story_5088_50880501_68_dialog_content = "Even after everything I said to him, he still lucked out and found this out from another one of the bosses.",
  ui_story_5088_50880501_69_dialog_content = "I think it's called Star Crest?",
  ui_story_5088_50880501_70_dialog_content = "...",
  ui_story_5088_50880501_71_dialog_content = "He's prying into the secret of the Star Warriors...",
  ui_story_5088_50880501_72_dialog_content = "I... have to carry out my mission... And stop him...",
  ui_story_5088_50880501_73_dialog_content = "But...",
  ui_story_5088_50880501_74_dialog_content = "I want to help them no matter what.",
  ui_story_5088_50880501_75_dialog_content = "I should give it to him tomorrow.",
  ui_story_5088_50880501_76_dialog_content = "Come out and face me, you cowards.",
  ui_story_5088_50880501_77_dialog_content = "Th-The Raven Hunter?! Not again!",
  ui_story_5088_50880501_78_dialog_content = "Why won't you leave us alone?! We're just trying to shake her down for a little money, that's all!",
  ui_story_5088_50880501_79_dialog_content = "What makes you think she has anything worth stealing?",
  ui_story_5088_50880501_80_dialog_content = "Why wouldn't she? She's been working for the Cloudrover Guild and is even friends with that Caelestite guy.",
  ui_story_5088_50880501_81_dialog_content = "Sorry to disappoint you, money-grubbing idiots, but that thing is completely worthless.",
  ui_story_5088_50880501_82_dialog_content = "But trying to steal a worthless object is still a crime. Prepare to be punished!",
  ui_story_5088_50880502_1_dialog_content = "Oh? Looks like I'm too late to join the fun.",
  ui_story_5088_50880502_2_dialog_content = "Still, I knew I would find you here.",
  ui_story_5088_50880502_3_dialog_content = "...",
  ui_story_5088_50880502_4_dialog_content = "What's wrong? You've been acting different lately.",
  ui_story_5088_50880502_5_dialog_content = "And you're going a lot harder on the bad guys too.",
  ui_story_5088_50880502_6_dialog_content = "It's nothing. Why are you out this late, anyway? Don't you have work in the daytime?",
  ui_story_5088_50880502_7_dialog_content = "I do... But that's okay.",
  ui_story_5088_50880502_8_dialog_content = "It's always more important to hear my friends out.",
  ui_story_5088_50880502_9_dialog_content = "I have nothing to say. We've only known each other for two years, and we only run into each other at night sometimes. Would you really call that \"friendship\"?",
  ui_story_5088_50880502_10_dialog_content = "Two years is a long time, you know!",
  ui_story_5088_50880502_11_dialog_content = "What's more, we met each other because of our crime-fighting efforts. That makes us battle buddies!",
  ui_story_5088_50880502_12_dialog_content = "Battle buddies? Please. You don't even know my name.",
  ui_story_5088_50880502_13_dialog_content = "You're right, which is why I'd love to get to know you during the day too. I bet you're just as cool when you're not fighting bad guys!",
  ui_story_5088_50880502_14_dialog_content = "Sorry to disappoint you, but there's nothing interesting about me or my daily life.",
  ui_story_5088_50880502_15_dialog_content = "Especially not for someone like you... Who shines so bright all the time...",
  ui_story_5088_50880502_16_dialog_content = "Huh? Are you trying to say you're just an ordinary person during the day?",
  ui_story_5088_50880502_17_dialog_content = "Because I think you're way too powerful to be anything but extraordinary!",
  ui_story_5088_50880502_18_dialog_content = "In fact, I bet you can inspire others just like some of the best idols out there!",
  ui_story_5088_50880502_19_dialog_content = "... Don't be absurd.",
  ui_story_5088_50880502_20_dialog_content = "You know... There is something I'd like to talk about. It's trivial, but would you be willing to listen?",
  ui_story_5088_50880502_21_dialog_content = "Of course! And don't worry, no matter how important or how trivial it is, I promise to keep it a secret.",
  ui_story_5088_50880502_22_dialog_content = "A secret, huh? Heheh...",
  ui_story_5088_50880502_23_dialog_content = "The truth is, I was born into a unique clan, and all my life, I've been entrusted with carrying out a certain mission.",
  ui_story_5088_50880502_24_dialog_content = "To that end, I was taught to always observe things from a distance and to never get involved.",
  ui_story_5088_50880502_25_dialog_content = "Ours is a family of shadows that operates beyond the flow of time. That's why we must keep ourselves hidden during the day.",
  ui_story_5088_50880502_26_dialog_content = "But now... The ones we were sworn to protect... There aren't many of them left.",
  ui_story_5088_50880502_27_dialog_content = "Wow! It sounds like your family is protecting some kind of rare creature!",
  ui_story_5088_50880502_28_dialog_content = "How could you think that's not important? Protecting something as your mission in life requires lots of focus and caution.",
  ui_story_5088_50880502_29_dialog_content = "I think it's incredible that you're able to keep your light hidden for the sake of your mission.",
  ui_story_5088_50880502_30_dialog_content = "A \"rare creature\"... That's not entirely wrong, I suppose. In any case, if I fail to carry out my mission, then it will more or less end with me.",
  ui_story_5088_50880502_31_dialog_content = "Because that person... I'm not sure that person is capable of fulfilling the prophecy.",
  ui_story_5088_50880502_32_dialog_content = "And then my clan will be bound for the rest of time.",
  ui_story_5088_50880502_33_dialog_content = "But beyond that, I... I just want to help that certain group of people.",
  ui_story_5088_50880502_34_dialog_content = "But I made a vow to protect their secrets, so I can only watch over them in silence. I can't betray my vow.",
  ui_story_5088_50880502_35_dialog_content = "Is that what's been bothering you?",
  ui_story_5088_50880502_36_dialog_content = "You've been taking out your frustration on the bad guys because of that?",
  ui_story_5088_50880502_37_dialog_content = "For various reasons I can't discuss, my ancestors were able to imbue some of their memories into our family heirloom, which has been passed down for generations.",
  ui_story_5088_50880502_38_dialog_content = "Through it, I can hear their anger and regrets.",
  ui_story_5088_50880502_39_dialog_content = "But the lord once told us not to involve anyone else for his sake.",
  ui_story_5088_50880502_40_dialog_content = "Ever since then, we've kept hidden and watched in silence, waiting for the prophesied one to fulfill our mission and free us all.",
  ui_story_5088_50880502_41_dialog_content = "But the prophesied one's people... They were all...",
  ui_story_5088_50880502_42_dialog_content = "I can't say I understand very much of what you're saying.",
  ui_story_5088_50880502_43_dialog_content = "But it sounds like you lead a very important life... And a lonely one, at that.",
  ui_story_5088_50880502_44_dialog_content = "Your clan was entrusted with their mission a long time ago, right? It's impressive that you've stayed true to it after all these years.",
  ui_story_5088_50880502_45_dialog_content = "And that can only be the result of unwavering faith and resolve.",
  ui_story_5088_50880502_46_dialog_content = "Something tells me that your ancestor, the one who made that vow, felt an incredible sense of love and compassion for the ones he swore to protect.",
  ui_story_5088_50880502_47_dialog_content = "Which makes me assume that they wouldn't want you to be so passive about your mission.",
  ui_story_5088_50880502_48_dialog_content = "Huh?",
  ui_story_5088_50880502_49_dialog_content = "If you take action to help the ones you've sworn to protect, I think it would better fulfill your ancestor's wishes. Wouldn't you agree?",
  ui_story_5088_50880502_50_dialog_content = "Besides, in our two years of fighting crime together, I've never known you to be very passive about anything.",
  ui_story_5088_50880502_51_dialog_content = "Waiting for someone else to save you like a damsel in distress... It's not like you at all.",
  ui_story_5088_50880502_52_dialog_content = "I think there's still a lot you can do to fulfill your mission.",
  ui_story_5088_50880502_53_dialog_content = "You don't have to break your oath, but with a few nudges in the right direction... You might be able to realize your ancestor's goals.",
  ui_story_5088_50880502_54_dialog_content = "You really think so?",
  ui_story_5088_50880502_55_dialog_content = "Of course I do!",
  ui_story_5088_50880502_56_dialog_content = "... Thank you.",
  ui_story_5088_50880502_57_dialog_content = "You're absolutely right. My ancestors couldn't make it to the prophesied day, but I am...",
  ui_story_5088_50880502_58_dialog_content = "At the very least, I should try to do something.",
  ui_story_5088_50880502_59_dialog_content = "But you already knew that, didn't you?",
  ui_story_5088_50880502_60_dialog_content = "... Yes. It's just that I've always been afraid of making things worse.",
  ui_story_5088_50880502_61_dialog_content = "But I hate standing by while they still need my help.",
  ui_story_5088_50880502_62_dialog_content = "When it comes to prophecies, there always has to be someone to make them come true.",
  ui_story_5088_50880502_63_dialog_content = "That's why you can't rely on other people to make things happen. You have to do it yourself.",
  ui_story_5088_50880502_64_dialog_content = "That's one of the basic principles of being an idol... Er, I mean a hero!",
  ui_story_5088_50880502_65_dialog_content = "Thank you, Goldie.",
  ui_story_5088_50880502_66_dialog_content = "I'll find a way to help them without breaking my vow.",
  ui_story_5088_50880502_67_dialog_content = "It's not a big deal... Wait, you know who I am?!?",
  ui_story_5088_50880502_68_dialog_content = "H-Hey, get back here! You've got some explaining to do!",
  ui_story_5088_50880502_69_dialog_content = "It's not fair if I don't get to know your identity too! Come back!",
  ui_story_5088_50880601_1_dialog_content = "(Casta brought me another emblem. Just like the other one, I don't recognize the design engraved on it.)",
  ui_story_5088_50880601_2_dialog_content = "(Are these... musical notes?)",
  ui_story_5088_50880601_3_dialog_content = "Just so you know, if we notice anything wrong with you, we're stopping you right away.",
  ui_story_5088_50880601_4_dialog_content = "That's our condition.",
  ui_story_5088_50880601_5_dialog_content = "Don't worry, I won't push myself too hard.",
  ui_story_5088_50880601_6_dialog_content = "... I'll make something special for you to try once you return from our time.",
  ui_story_5088_50880601_7_dialog_content = "Try not to get lost in the dream.",
  ui_story_5088_50880601_8_dialog_content = "... How much time has passed since then? Was Czerny able to safely return to Eraveil?",
  ui_story_5088_50880601_9_dialog_content = "I pray for his peace, and hope that he'll forget about us someday and live a long and happy life.",
  ui_story_5088_50880601_10_dialog_content = "I'm sorry, Ludweiss, but you'll have to wait with us for a while longer...",
  ui_story_5088_50880601_11_dialog_content = "I can't keep track of time any longer. So many things are starting to blur together.",
  ui_story_5088_50880601_12_dialog_content = "I think I'm nearly at my limit... I need to write down one last warning for the descendants of the Longinus clan...",
  ui_story_5088_50880601_13_dialog_content = "\"Stay away from the depths of the cave.\"",
  ui_story_5088_50880601_14_dialog_content = "Urgh... Even doing something as simple as this leaves me completely exhausted...",
  ui_story_5088_50880601_15_dialog_content = "I should've been completely corrupted by now, but they haven't stopped yet.",
  ui_story_5088_50880601_16_dialog_content = "How much longer can I stay in control? Is it... truly beyond me now?",
  ui_story_5088_50880601_17_dialog_content = "You lied to me, Ludweiss.",
  ui_story_5088_50880601_18_dialog_content = "No... What just happened?! How could I blame Ludweiss for this?",
  ui_story_5088_50880601_19_dialog_content = "My friends... I've failed you too...",
  ui_story_5088_50880601_20_dialog_content = "Is it truly impossible to use my memories to resist the passage of time?",
  ui_story_5088_50880601_21_dialog_content = "Please... Help me...",
  ui_story_5088_50880601_22_dialog_content = "<color=#e8d9bb>The air fills with loud and excited cheers—</color>",
  ui_story_5088_50880601_23_dialog_content = "...?",
  ui_story_5088_50880601_24_dialog_content = "Praise the Star Warriors, the heroes who eradicated the Eclipsites!",
  ui_story_5088_50880601_25_dialog_content = "As your king, it is my distinct honor to present you with these awards.",
  ui_story_5088_50880601_26_dialog_content = "Heroes! Heroes! Heroes! Heroes!",
  ui_story_5088_50880601_27_dialog_content = "Ah... The moment of our greatest glory...",
  ui_story_5088_50880601_28_dialog_content = "Make your vows before the gods, and receive the honor you have so justly earned.",
  ui_story_5088_50880601_29_dialog_content = "Step forth.",
  ui_story_5088_50880601_30_dialog_content = "So long as a single righteous person remains in this world, I shall always be ready to sacrifice my life for it.",
  ui_story_5088_50880601_31_dialog_content = "You are the noble shield of the kingdom, steadfast and willing to defend the weak and innocent. With the gods as my witnesses, I hereby bestow the title of \"Regal\" upon you!",
  ui_story_5088_50880601_32_dialog_content = "I vow to become a river of castigating fire, and purge the world of wickedness with my flames.",
  ui_story_5088_50880601_33_dialog_content = "Your flames burn brightest as you lead the charge into battle. With the gods as my witnesses, I hereby bestow the title of \"Frostfire\" upon you!",
  ui_story_5088_50880601_34_dialog_content = "I vow to preserve hope, and become the light which guides the suffering and the desperate!",
  ui_story_5088_50880601_35_dialog_content = "With your brilliant lance, you sunder the darkness and herald the coming dawn. With the gods as my witnesses, I hereby bestow the title of \"Requiem\" upon you!",
  ui_story_5088_50880601_36_dialog_content = "I vow to protect every single moment of peace, and hold fast to my staff even if my body perishes.",
  ui_story_5088_50880601_37_dialog_content = "Your quiet light quells the turmoil of our world in the name of peace. With the gods as my witnesses, I hereby bestow the title of \"Mythos\" upon you!",
  ui_story_5088_50880601_38_dialog_content = "Woo-hoo—!!!",
  ui_story_5088_50880601_39_dialog_content = "It's your turn now, Captain.",
  ui_story_5088_50880601_40_dialog_content = "Step forth and make your vow, Achilles.",
  ui_story_5088_50880601_41_dialog_content = "May the gods bear witness to my oath! For the sake of my cherished ones, I vow to sacrifice everything until time reduces me to dust!",
  ui_story_5088_50880601_42_dialog_content = "I have no regrets—",
  ui_story_5088_50880601_43_dialog_content = "Ah... It was just a dream... A rare and pleasant one, no less.",
  ui_story_5088_50880601_44_dialog_content = "Will I ever get to see how those people live their peaceful lives? Does the kingdom still need others to sacrifice themselves for it?",
  ui_story_5088_50880601_45_dialog_content = "<color=#e8d9bb>Crack—</color>",
  ui_story_5088_50880601_46_dialog_content = "?",
  ui_story_5088_50880601_47_dialog_content = "Is someone there...?",
  ui_story_5088_50880601_48_dialog_content = "Huh? Argh, not again! How could it cut off right there?!",
  ui_story_5088_50880601_49_dialog_content = "Alright PlayerName, that's enough for the day. You did a good job, now come and eat with us!",
  ui_story_5088_50880601_50_dialog_content = "He may not look like it, but Adras is a pretty decent cook!",
  ui_story_5088_50880601_51_dialog_content = "I have to be if I want to feed those children properly... Hmm?",
  ui_story_5088_50880601_52_dialog_content = "I...",
  ui_story_5088_50880601_53_dialog_content = "Don't push yourself too hard. It's fine if you can't remember for now.",
  ui_story_5088_50880601_54_dialog_content = "...",
  ui_story_5088_50880601_55_dialog_content = "Come on Adras, let's go eat.",
  ui_story_5088_50880601_56_dialog_content = "Sure.",
  ui_story_5088_50880601_57_dialog_content = "You're the greatest, Adras! Ah, I've been dying to eat this for the last two thousand years!",
  ui_story_5088_50880601_58_dialog_content = "Eh? Who's there?!",
  ui_story_5088_50880601_59_dialog_content = "Hold it right there! This place belongs to the Blue Wolverines.",
  ui_story_5088_50880601_60_dialog_content = "I'm well aware of that.",
  ui_story_5088_50880601_61_dialog_content = "My clan left something in your possession. I'm here to take it back.",
  ui_story_5088_50880601_62_dialog_content = "Huh?",
  ui_story_5088_50880601_63_dialog_content = "Get lost!",
  ui_story_5088_50880601_64_dialog_content = "Then I guess I'll have to show you.",
  ui_story_5088_50880601_65_dialog_content = "Witness me—For I am death.",
  ui_story_5088_50880602_1_dialog_content = "Wow, you sure showed up early!",
  ui_story_5088_50880602_2_dialog_content = "Lady Jeriah asked me to personally deliver this to you. It must be very urgent.",
  ui_story_5088_50880602_3_dialog_content = "Until next time.",
  ui_story_5088_50880602_4_dialog_content = "Uh... Miss Mithra?",
  ui_story_5088_50880602_5_dialog_content = "Yes?",
  ui_story_5088_50880602_6_dialog_content = "I'm sure this journal is really important, but... I don't need to use my powers on it to know that it belonged to the Longinus clan.",
  ui_story_5088_50880602_7_dialog_content = "I'm already familiar with their wavelength.",
  ui_story_5088_50880602_8_dialog_content = "...",
  ui_story_5088_50880602_9_dialog_content = "As a Caelestite, discerning different people is something that comes naturally to me.",
  ui_story_5088_50880602_10_dialog_content = "I don't sense Jeriah from this journal at all, but I do sense a very familiar presence on it... Yours.",
  ui_story_5088_50880602_11_dialog_content = "... I wasn't entirely sure at that day, since we had only met once before then.",
  ui_story_5088_50880602_12_dialog_content = "But when you showed up with Tweety the very next day, I knew it was you.",
  ui_story_5088_50880602_13_dialog_content = "...",
  ui_story_5088_50880602_14_dialog_content = "Regardless of the circumstances, you saved me and I'm grateful for it. There must be a reason to keep your identity hidden, right?",
  ui_story_5088_50880602_15_dialog_content = "As for this notebook... Why would you use Lady Jeriah's name to bring it to me?",
  ui_story_5088_50880602_16_dialog_content = "Isn't it... important to your family?",
  ui_story_5088_50880602_17_dialog_content = "Alright, let's take a quick head count—By a show of hands, how many of us are ungrateful jerks? Go ahead, raise your hands.",
  ui_story_5088_50880602_18_dialog_content = "...",
  ui_story_5088_50880602_19_dialog_content = "Good! Looks like none of us are selfish ingrates.",
  ui_story_5088_50880602_20_dialog_content = "Now then, let's invite Cynthia to say a few words!",
  ui_story_5088_50880602_21_dialog_content = "... Let's go.",
  ui_story_5088_50880602_22_dialog_content = "As expected of a Caelestite.",
  ui_story_5088_50880602_23_dialog_content = "At this point, you may know even more than I do. It seems there's no reason to keep up this charade anymore...",
  ui_story_5088_50880602_24_dialog_content = "It's just as you said. My name is Mithra Longinus.",
  ui_story_5088_50880602_25_dialog_content = "My family, the Longinus Clan, has patiently waited for the arrival of a prophesied Caelestite for over two thousand years.",
  ui_story_5088_50880602_26_dialog_content = "Two thousand years...?",
  ui_story_5088_50880602_27_dialog_content = "Heheh, I doubt even Lady Ludweiss knew that her prophecy would take this long.",
  ui_story_5088_50880602_28_dialog_content = "For ages, our clan has watched the world's changes from the shadows.",
  ui_story_5088_50880602_29_dialog_content = "Even after all these years, not once have we forgotten our purpose: to stop anyone from uncovering the secrets of the stars.",
  ui_story_5088_50880602_30_dialog_content = "And yet, you've never tried to stop me from digging around. Is it because I'm a Caelestite?",
  ui_story_5088_50880602_31_dialog_content = "Correct. And not only that, you are the Caelestite from Lady Ludweiss' prophecy.",
  ui_story_5088_50880602_32_dialog_content = "Our clan has always permitted Caelestites to investigate our secret for centuries, but we've never explicitly asked for their help. I'm sure you know the reason why—",
  ui_story_5088_50880602_33_dialog_content = "Lord Achilles can't be sealed away, but his corruption can't be reversed either.",
  ui_story_5088_50880602_34_dialog_content = "His body is infused with the power of darkness. Ordinary Caelestites, bound by their innate shackles, could never hope to control that kind of power.",
  ui_story_5088_50880602_35_dialog_content = "Attempting to sense his mind would cause you to lose your own mind at best, but at worst... The backlash from the fallen star's whispers could kill you.",
  ui_story_5088_50880602_36_dialog_content = "... The Caelestites in Eraveil are unrivaled in their kindness and compassion. Because of that, asking them for help would be no different than putting their lives at stake.",
  ui_story_5088_50880602_37_dialog_content = "Their chances for salvation are thin, and Lord Achilles refuses to let any more people sacrifice themselves for their sake.",
  ui_story_5088_50880602_38_dialog_content = "So you kept all of these to yourselves instead of telling the Caelestites?",
  ui_story_5088_50880602_39_dialog_content = "... There are more reasons than that, but yes. In the end, we decided that waiting in silence was the better choice.",
  ui_story_5088_50880602_40_dialog_content = "Before Lady Ludweiss passed away, she claimed to have seen a Caelestite from thousands of years in the future.",
  ui_story_5088_50880602_41_dialog_content = "And by that Caelestite's side was Lord Adras, who had been freed from his seal.",
  ui_story_5088_50880602_42_dialog_content = "Since then, we've been patiently awaiting the realization of this prophecy.",
  ui_story_5088_50880602_43_dialog_content = "But even after two millennia and the upheaval of our entire world... The day we've been waiting for still hasn't come to pass.",
  ui_story_5088_50880602_44_dialog_content = "... And now I'm the only Caelestite left in the world. For the last seventeen years or so, the world thought that our people had been completely wiped out... But then I appeared.",
  ui_story_5088_50880602_45_dialog_content = "But even after that, your family still stayed strong and waited.",
  ui_story_5088_50880602_46_dialog_content = "No... There's nothing strong about me. In fact, my heart had been full of doubt...",
  ui_story_5088_50880602_47_dialog_content = "I didn't believe that this so-called \"savior\" was the only one who could free us and Lord Achilles from our fate.",
  ui_story_5088_50880602_48_dialog_content = "Through my efforts, I eventually realized that my ancestors felt the same way I did and that we faced similar obstacles in our lives.",
  ui_story_5088_50880602_49_dialog_content = "Without a Caelestite, even just breaking the seal on the Star Warriors would become impossible.",
  ui_story_5088_50880602_50_dialog_content = "But still, there has to be something I could do...",
  ui_story_5088_50880602_51_dialog_content = "So that's why you brought this to me...",
  ui_story_5088_50880602_52_dialog_content = "That journal contains the Longinus' most profound wishes and experiences over the ages.",
  ui_story_5088_50880602_53_dialog_content = "Whether you can get guidance from it or not is up to you.",
  ui_story_5088_50880602_54_dialog_content = "Doing this isn't a violation of my vow either.",
  ui_story_5088_50880602_55_dialog_content = "Thank you. I'll take good care of it and learn as much as I can.",
  ui_story_5088_50880602_56_dialog_content = "They're counting on you... And so am I.",
  ui_story_5088_50880602_57_dialog_content = "(It sounds like she thinks there's still a chance to save Achilles...)",
  ui_story_5088_50880602_58_dialog_content = "(No, that can't be right. If Achilles really is dead and the other Star Warriors were awakened by me, then there's no reason for her to worry about it.)",
  ui_story_5088_50880602_59_dialog_content = "(But since she's still carrying out her duties, then that must mean... Achilles might still be alive somewhere, which means there's still a chance...)",
  ui_story_5088_50880602_60_dialog_content = "I have to go back to that cave!",
  ui_story_5088_50880602_61_dialog_content = "Not bad, PlayerName! How'd you know we would go back to that place?",
  ui_story_5088_50880602_62_dialog_content = "Huh? What are you guys doing?",
  ui_story_5088_50880602_63_dialog_content = "We have never been ungrateful people.",
  ui_story_5088_50880602_64_dialog_content = "Someone used their powerful emotions to seal us away.",
  ui_story_5088_50880602_65_dialog_content = "And we want to know who that person was.",
  ui_story_5088_50880602_66_dialog_content = "That's right, and we also want to know exactly what he did to us.",
  ui_story_5088_50880602_67_dialog_content = "If it was just a simple act of betrayal, there was no need to seal away our emotions as well.",
  ui_story_5088_50880602_68_dialog_content = "But... We're the ones who killed him... If you learn the story behind this...",
  ui_story_5088_50880602_69_dialog_content = "He was the one who taught me that my flames can be used to help people.",
  ui_story_5088_50880602_70_dialog_content = "He stopped the Eclipsites from destroying my forest, and showed me how to use my powers to protect this world.",
  ui_story_5088_50880602_71_dialog_content = "He gave me a reason to keep living by suggesting I quell the rebellion.",
  ui_story_5088_50880602_72_dialog_content = "Heheh, he pulled me out of the darkness and gave me a new objective in life.",
  ui_story_5088_50880602_73_dialog_content = "You guys...",
  ui_story_5088_50880602_74_dialog_content = "So as far as we're concerned, that guy isn't Claymore or some monster. His name is Achilles.",
  ui_story_5088_50880602_75_dialog_content = "We can't let you do this all by yourself, and we certainly can't pretend that he's evil and call it a day.",
  ui_story_5088_50880602_76_dialog_content = "Even though I remember him now... I still can't help but feel angry...",
  ui_story_5088_50880602_77_dialog_content = "But we still need to know the truth.",
  ui_story_5088_50880602_78_dialog_content = "These feelings are real. We're sure of it.",
  ui_story_5088_50880602_79_dialog_content = "Heh, we must've really hated him before, since we wanted to kill each other as soon as we locked eyes.",
  ui_story_5088_50880602_80_dialog_content = "True... We make it sound trivial sometimes, but the truth of the matter is he ran us through with his sword without saying a word.",
  ui_story_5088_50880602_81_dialog_content = "He was stronger than all of us, and he tried to kill us without saying anything... Fighting with him was inevitable.",
  ui_story_5088_50880602_82_dialog_content = "But remember, our reason for going there is to learn the truth and confirm whether or not he's still alive. The only difference now is that our minds are calmer and clearer than before.",
  ui_story_5088_50880602_83_dialog_content = "... Those are our thoughts on the matter, PlayerName.",
  ui_story_5088_50880602_84_dialog_content = "No matter how painful or cruel it may be, we still want to know the truth.",
  ui_story_5088_50880602_85_dialog_content = "For our memories, and for his honor.",
  ui_story_5088_50880602_86_dialog_content = "We can't just forget about everything like this.",
  ui_story_5088_50880602_87_dialog_content = "And because of our undying bodies, there's still hope...",
  ui_story_5088_50880602_88_dialog_content = "Even if there's only a slim chance of saving him...",
  ui_story_5088_50880602_89_dialog_content = "We'll do everything we can to make it happen, even if he truly betrayed us in the past.",
  ui_story_5088_50880602_90_dialog_content = "So let's all go together!",
  ui_story_5088_50880602_91_dialog_content = "...",
  ui_story_5088_50880602_92_dialog_content = "Alright!",
  ui_story_5088_50880701_1_dialog_content = "<color=#e8d9bb>According to the notebook, the Longinus Clan eventually succeeded in uncovering Czerny's whereabouts.</color>",
  ui_story_5088_50880701_2_dialog_content = "<color=#e8d9bb>After returning to Eraveil, he made no mention of the Star Warriors to anyone.</color>",
  ui_story_5088_50880701_3_dialog_content = "<color=#e8d9bb>Czerny's parents, who were relieved that their son had finally come home, welcomed him with open arms, and they resumed their happy lives together.</color>",
  ui_story_5088_50880701_4_dialog_content = "<color=#e8d9bb>But by then, Czerny's personality-defining arrogance had been replaced with a calm and gentle demeanor.</color>",
  ui_story_5088_50880701_5_dialog_content = "<color=#e8d9bb>He never participated in another competition, and instead devoted his efforts to teaching music.</color>",
  ui_story_5088_50880701_6_dialog_content = "<color=#e8d9bb>His most famous works were both tragic and solemn, and soon became the signature melodies of the Caelestite holiday of Windelion.</color>",
  ui_story_5088_50880701_7_dialog_content = "<color=#e8d9bb>Later in his life, he erected a nameless tombstone in the place where all Caelestites were laid to rest. Every year on Windelion, he would visit the tombstone and pay his respects.</color>",
  ui_story_5088_50880701_8_dialog_content = "<color=#e8d9bb>Most people had no idea who he was mourning. Out of respect for this music teacher, no one dared to ask or even speculate as to who it may be.</color>",
  ui_story_5088_50880701_9_dialog_content = "<color=#e8d9bb>Left alone after the death of his parents, Czerny committed himself to the adoption and education of Eraveil's orphans, the sons and daughters of those who had been exiled. In time, he became one of Eraveil's most revered and beloved teachers.</color>",
  ui_story_5088_50880701_10_dialog_content = "Thanks to Queen Bethlehem's map, we were able to return to this place fairly quickly.",
  ui_story_5088_50880701_11_dialog_content = "I wonder what her connection is to all of this... She wouldn't tell me when I asked...",
  ui_story_5088_50880701_12_dialog_content = "Hey Freya, I just remembered something! That name, \"Bethlehem\"... Didn't someone in your family have...",
  ui_story_5088_50880701_13_dialog_content = "Wow! Did someone bust out of the cave from here? Why have we never noticed this opening before?",
  ui_story_5088_50880701_14_dialog_content = "Everything in here is frozen solid with no hope of ever thawing out...",
  ui_story_5088_50880701_15_dialog_content = "...",
  ui_story_5088_50880701_16_dialog_content = "?",
  ui_story_5088_50880701_17_dialog_content = "No one else is in the cave, but I don't sense his presence either.",
  ui_story_5088_50880701_18_dialog_content = "... Does that mean we truly killed him last time?",
  ui_story_5088_50880701_19_dialog_content = "Let's not be hasty. I found a few tattered scrolls at the other entrance to the cave.",
  ui_story_5088_50880701_20_dialog_content = "That should have been the only way in or out, which means this opening must have been made afterward.",
  ui_story_5088_50880701_21_dialog_content = "Could it be that he broke through the cave's walls from here and escaped?",
  ui_story_5088_50880701_22_dialog_content = "The magic formation was holding him in place, not us. It should have been impossible for him to leave this place.",
  ui_story_5088_50880701_23_dialog_content = "Then maybe he was in a really bad mood one day, so he took it out on the cave wall and left this giant hole!",
  ui_story_5088_50880701_24_dialog_content = "Just let me try sensing these scroll fragments first.",
  ui_story_5088_50880701_25_dialog_content = "Alright, but just because I can heal you with my magic doesn't mean you can push yourself too hard. Got it?",
  ui_story_5088_50880701_26_dialog_content = "I know.",
  ui_story_5088_50880701_27_option_content = "Psychic Scan",
  ui_story_5088_50880701_28_dialog_content = "When darkness passes, people no longer need the stars to guide their way.",
  ui_story_5088_50880701_29_dialog_content = "They are no longer soldiers of that kingdom.",
  ui_story_5088_50880701_30_dialog_content = "Day Seven: May You Live Freely From Now On.",
  ui_story_5088_50880701_31_dialog_content = "Who's there? Stay out of this cave!",
  ui_story_5088_50880701_32_dialog_content = "<color=#e8d9bb>Pat, pat, pat—</color>",
  ui_story_5088_50880701_33_dialog_content = "<color=#e8d9bb>A young Caelestite girl wipes the dust from the nameless tombstone and lays fresh flowers before it.</color>",
  ui_story_5088_50880701_34_dialog_content = "...",
  ui_story_5088_50880701_35_dialog_content = "Master Czerny, I cleaned up Lady Ludweiss again, just like you asked.",
  ui_story_5088_50880701_36_dialog_content = "Well done, little one. Thank you.",
  ui_story_5088_50880701_37_dialog_content = "But... May I ask why you still look so sad, Master?",
  ui_story_5088_50880701_38_dialog_content = "Everyone says that Windelion is a day to remember the dearly departed and offer them our thoughts and prayers.",
  ui_story_5088_50880701_39_dialog_content = "So we have to be strong and show them that we're happy.",
  ui_story_5088_50880701_40_dialog_content = "...",
  ui_story_5088_50880701_41_dialog_content = "That's what you taught us, Master Czerny...",
  ui_story_5088_50880701_42_dialog_content = "But every Windelion, you look like you're in so much pain.",
  ui_story_5088_50880701_43_dialog_content = "I'm sorry, little one... But the ones who I mourn will never hear my thoughts. Destiny has seen to that.",
  ui_story_5088_50880701_44_dialog_content = "You're a kind-hearted soul. Despite your young age, you can already sense the pain in other people's hearts.",
  ui_story_5088_50880701_45_dialog_content = "But you should know the kind-hearted will always suffer more than anyone else.",
  ui_story_5088_50880701_46_dialog_content = "You took me in and raised me, Master Czerny. That's why I want to be just like you.",
  ui_story_5088_50880701_47_dialog_content = "Besides, you won't feel so bad if I'm able to help you, right?",
  ui_story_5088_50880701_48_dialog_content = "?!",
  ui_story_5088_50880701_49_dialog_content = "If I try a little harder, then maybe you'll be able to live more happily someday...",
  ui_story_5088_50880701_50_dialog_content = "And when that day comes... Maybe you'll finally be able to say your goodbyes to Lady Ludweiss on Windelion. Right, Master Czerny?",
  ui_story_5088_50880701_51_dialog_content = "Ah...",
  ui_story_5088_50880701_52_dialog_content = "<color=#e8d9bb>As the mournful song of Windelion begins to play, Czerny falls to his knees in pain.</color>",
  ui_story_5088_50880701_53_dialog_content = "Why are you crying, Master Czerny?",
  ui_story_5088_50880701_54_dialog_content = "Did I say something wrong? I'm sorry... Please don't cry.",
  ui_story_5088_50880701_55_dialog_content = "I... What have I been doing all this time...?",
  ui_story_5088_50880701_56_dialog_content = "What's wrong, Master Czerny? You haven't done anything wrong—everyone loves you!",
  ui_story_5088_50880701_57_dialog_content = "The music you play for us is just wonderful, and your lessons are so interesting...",
  ui_story_5088_50880701_58_dialog_content = "Please don't cry anymore...",
  ui_story_5088_50880701_59_dialog_content = "At this point, can I still face you all with an open heart? The symphony I gave you...",
  ui_story_5088_50880701_60_dialog_content = "Who's there? No one's allowed in the cave!",
  ui_story_5088_50880701_61_dialog_content = "Wah... the star we all live to serve. You're real...",
  ui_story_5088_50880701_62_dialog_content = "Longinus...?",
  ui_story_5088_50880701_63_dialog_content = "Get up, now. Why do you look so... down?",
  ui_story_5088_50880701_64_dialog_content = "Did something terrible happen to you?",
  ui_story_5088_50880701_65_dialog_content = "Lumopolis is in a state of great tumult, and our family has been implicated amid the mayhem.",
  ui_story_5088_50880701_66_dialog_content = "Now, we have become nothing but the sorrowful shadows of Lower Lumopolis.",
  ui_story_5088_50880701_67_dialog_content = "Our family faces unprecedented turmoil, and many have lost their faith.",
  ui_story_5088_50880701_68_dialog_content = "As the new head of the family, I... must carry the weight of our future.",
  ui_story_5088_50880701_69_dialog_content = "Do you need any help?",
  ui_story_5088_50880701_70_dialog_content = "No, I need nothing, my lord.",
  ui_story_5088_50880701_71_dialog_content = "In this darkest of nights, I solely wish to pay my respects...",
  ui_story_5088_50880701_72_dialog_content = "By your command, two generations of family heads have come and gone without being graced by your presence. This is why many believe you are but a legend of our lineage.",
  ui_story_5088_50880701_73_dialog_content = "Especially in such bleak times, no one believes in the greatness we once served... They've begun to lose hope.",
  ui_story_5088_50880701_74_dialog_content = "Even I... feel a shameful doubt in my heart.",
  ui_story_5088_50880701_75_dialog_content = "For the sake of the clan, you should give up. I will not blame you.",
  ui_story_5088_50880701_76_dialog_content = "But now, I have seen you.",
  ui_story_5088_50880701_77_dialog_content = "I'll end all the disputes. The shadow over Longinus is not without a guiding star.",
  ui_story_5088_50880701_78_dialog_content = "You...",
  ui_story_5088_50880701_79_dialog_content = "I shall return to Lumopolis, leading my kin in the shadows, continuing to defy that unfathomable fate.",
  ui_story_5088_50880701_80_dialog_content = "... Who are you to Dominic?",
  ui_story_5088_50880701_81_dialog_content = "Czerny?",
  ui_story_5088_50880701_82_dialog_content = "The Star Warrior recognizes you... Are you the Caelestite who once lent us a hand? Dominic is my uncle.",
  ui_story_5088_50880701_83_dialog_content = "Lent a hand? Me?",
  ui_story_5088_50880701_84_dialog_content = "Hahahaha!",
  ui_story_5088_50880701_85_dialog_content = "What folly have I been engaged in? Clearly, I am the Caelestite, the one who would aid Achilles, yet I have accomplished nothing.",
  ui_story_5088_50880701_86_dialog_content = "Why have you returned...?",
  ui_story_5088_50880701_87_dialog_content = "I wanted to visit you, Achilles.",
  ui_story_5088_50880701_88_dialog_content = "I cannot let go, nor can I face the truth.",
  ui_story_5088_50880701_89_dialog_content = "But when I heard all this at the cave entrance... I... could not help but be moved by this one's conviction.",
  ui_story_5088_50880701_90_dialog_content = "I should continue tending to this unfinished business.",
  ui_story_5088_50880702_1_dialog_content = "<color=#e8d9bb>If you see this, people of the future, please witness my final record.</color>",
  ui_story_5088_50880702_2_dialog_content = "<color=#e8d9bb>Due to Achilles' worsening condition, I must distance myself somewhat and continue the work of years past.</color>",
  ui_story_5088_50880702_3_dialog_content = "<color=#e8d9bb>Now I am calmer, calm enough to systematically leave this information.</color>",
  ui_story_5088_50880702_4_dialog_content = "<color=#e8d9bb>After this page, there should be four hundred and forty-three pages of research records.</color>",
  ui_story_5088_50880702_5_dialog_content = "<color=#e8d9bb>But even with all these scrolls, I've only just started making progress.</color>",
  ui_story_5088_50880702_6_dialog_content = "<color=#e8d9bb>Alas, I am now out of time...</color>",
  ui_story_5088_50880702_7_dialog_content = "Cough, cough... Cough, cough, cough...",
  ui_story_5088_50880702_8_dialog_content = "You've been coughing more than normal lately.",
  ui_story_5088_50880702_9_dialog_content = "It's too cold here. You should leave and see a doctor.",
  ui_story_5088_50880702_10_dialog_content = "This is no ailment, Achilles. This is... cough, cough... old age.",
  ui_story_5088_50880702_11_dialog_content = "...",
  ui_story_5088_50880702_12_dialog_content = "Time is truly merciless.",
  ui_story_5088_50880702_13_dialog_content = "I thought I had so much time left...",
  ui_story_5088_50880702_14_dialog_content = "At this age, I envy you all. If only I could live forever...",
  ui_story_5088_50880702_15_dialog_content = "...",
  ui_story_5088_50880702_16_dialog_content = "Achilles, are you still awake?",
  ui_story_5088_50880702_17_dialog_content = "... Yes.",
  ui_story_5088_50880702_18_dialog_content = "If I hear the monster in my heart approaching, I'll roar at it instantly, Czerny.",
  ui_story_5088_50880702_19_dialog_content = "I was just pondering.",
  ui_story_5088_50880702_20_dialog_content = "I might be as helpless as you, and my brain is slowing down. If I don't give everything I've got, well, I can't even think.",
  ui_story_5088_50880702_21_dialog_content = "We are just a pair of old fossils.",
  ui_story_5088_50880702_22_dialog_content = "Hahaha... It's rare to hear you jest.",
  ui_story_5088_50880702_23_dialog_content = "But I have accomplished nothing, and now I am old and dying... In the end, it appears I was not the Caelestite of prophecy.",
  ui_story_5088_50880702_24_dialog_content = "Czerny, you need not despair. Time may bring on the dusk, but you have roared against it.",
  ui_story_5088_50880702_25_dialog_content = "Without you, I might have given up long ago.",
  ui_story_5088_50880702_26_dialog_content = "You mean to say, my fleeting flicker helped you withstand the overwhelming darkness?",
  ui_story_5088_50880702_27_dialog_content = "Indeed. Even I possess my fair share of frailties. Without the support of a friend like you, I could not have remained clear-headed for so long.",
  ui_story_5088_50880702_28_dialog_content = "I understand your resolve, so I will no longer urge you to leave. I hope you understand that you have already worked true miracles for me.",
  ui_story_5088_50880702_29_dialog_content = "You gave me hope—is that not enough to drive away the darkness?",
  ui_story_5088_50880702_30_dialog_content = "Hope...",
  ui_story_5088_50880702_31_dialog_content = "Just as Ludweiss gave me hope with the prophecy, imbuing me with the courage to move forward.",
  ui_story_5088_50880702_32_dialog_content = "You have done the same.",
  ui_story_5088_50880702_33_dialog_content = "... Ah!",
  ui_story_5088_50880702_34_dialog_content = "Yes... that must be it...",
  ui_story_5088_50880702_35_dialog_content = "All this time, my research was focused in the wrong direction!",
  ui_story_5088_50880702_36_dialog_content = "What do you mean?",
  ui_story_5088_50880702_37_dialog_content = "I was so fixated on achieving a perfect ending that I overlooked the fact that we still have a way to reach a compromise!",
  ui_story_5088_50880702_38_dialog_content = "The most important thing is your consciousness! As long as I preserve your consciousness, I know it will be enough!",
  ui_story_5088_50880702_39_dialog_content = "I have been researching how to stop your erosion and restore you to your former self, but I was stalled by the problem of your power.",
  ui_story_5088_50880702_40_dialog_content = "But the truth is, we don't need your body—we just need to find a way to preserve your consciousness!",
  ui_story_5088_50880702_41_dialog_content = "What does that mean?",
  ui_story_5088_50880702_42_dialog_content = "You, like the others, have undergone extensive augmentations, your body filled with the power of darkness.",
  ui_story_5088_50880702_43_dialog_content = "They were affected by the erosion to some extent, but after being sealed, that darkness was kept at bay by their strongest emotions.",
  ui_story_5088_50880702_44_dialog_content = "Their bodies, though having undergone Eclipsite transformation, gradually stabilized. With your magic formation's help, that rejection erosion won't happen again!",
  ui_story_5088_50880702_45_dialog_content = "You too! Even if I can't seal you, what if I pull your consciousness out of your body? Your body can remain in the magic formation!",
  ui_story_5088_50880702_46_dialog_content = "Maybe one day, your body will adapt to the erosion and stabilize, and that dark power won't drive you insane.",
  ui_story_5088_50880702_47_dialog_content = "Do you mean you have a way to extract and preserve my consciousness?",
  ui_story_5088_50880702_48_dialog_content = "Researching this will be easier than curing you directly.",
  ui_story_5088_50880702_49_dialog_content = "The hardest part will be finding a vessel that can temporarily hold \"you\" without any form of rejection.",
  ui_story_5088_50880702_50_dialog_content = "Hahaha! This truly is a ray of hope!",
  ui_story_5088_50880702_51_dialog_content = "Achilles, what Ludweiss left us wasn't a <color=#FFB400>prophecy</color>, but <color=#FFB400>hope</color>!",
  ui_story_5088_50880702_52_dialog_content = "<color=#FFB400>Hope</color>...",
  ui_story_5088_50880702_53_dialog_content = "Otherwise, why would she sacrifice herself knowing she was not to be the one who would solve this problem?",
  ui_story_5088_50880702_54_dialog_content = "Also, her method wasn't perfect.",
  ui_story_5088_50880702_55_dialog_content = "But because she believed in the future, believed in hope, she willingly sacrificed herself to pave the way for the one who would follow her.",
  ui_story_5088_50880702_56_dialog_content = "I am the one who now follows her!",
  ui_story_5088_50880702_57_dialog_content = "Hahaha! Achilles, I am the one who now follows her!",
  ui_story_5088_50880702_58_dialog_content = "I may not be the one spoken of in the prophecy, but I can still be the one spoken of in the prophecy!",
  ui_story_5088_50880702_59_dialog_content = "It seems you have finally realized the light you hold within.",
  ui_story_5088_50880702_60_dialog_content = "And my faith will be passed on to the next Caelestite!",
  ui_story_5088_50880702_61_dialog_content = "We will pass down a flame in the dark wilderness until our light illuminates this land of despair!",
  ui_story_5088_50880702_62_dialog_content = "Ludweiss, I finally understand your last words... I finally understand your last words!!!",
  ui_story_5088_50880702_63_dialog_content = "I don't need to complete everything myself—I just need to do what I can and then pass it on to the next Caelestite.",
  ui_story_5088_50880702_64_dialog_content = "I will also record my insights, becoming a messenger for future generations!",
  ui_story_5088_50880702_65_dialog_content = "A hundred years, a thousand years, two thousand years from now! One day, when your body stabilizes, a Caelestite will bring your consciousness back!",
  ui_story_5088_50880702_66_dialog_content = "I trust you, my friend. What do you need me to do?",
  ui_story_5088_50880702_67_dialog_content = "<color=#e8d9bb>So, to you reading this, my successor, please heed my words.</color>",
  ui_story_5088_50880702_68_dialog_content = "<color=#e8d9bb>I was once overly ambitious, believing myself to be the chosen savior, and thus I failed back then...</color>",
  ui_story_5088_50880702_69_dialog_content = "<color=#e8d9bb>But I also succeeded, as I did everything I could and passed the torch to you.</color>",
  ui_story_5088_50880702_70_dialog_content = "<color=#e8d9bb>Now, if you are willing, no matter how much or little you can do, I sincerely hope you can help keep this flame alive.</color>",
  ui_story_5088_50880702_71_dialog_content = "<color=#e8d9bb>We who came before you will always be grateful for your help.</color>",
  ui_story_5088_50880702_72_dialog_content = "<color=#e8d9bb>And if the ice and snow melt, and spring comes to this land of despair, please come here.</color>",
  ui_story_5088_50880702_73_dialog_content = "<color=#e8d9bb>Claymore awaits. Please tell him, \"Spring has arrived.\"</color>",
  ui_story_5088_50880801_1_dialog_content = "Show yourself.",
  ui_story_5088_50880801_2_dialog_content = "... When did you notice I was here?",
  ui_story_5088_50880801_3_dialog_content = "From the very beginning.",
  ui_story_5088_50880801_4_dialog_content = "Don't be fooled by Cynthia's staff and perpetually bamboozled appearance.",
  ui_story_5088_50880801_5_dialog_content = "She's the best scout in our team.",
  ui_story_5088_50880801_6_dialog_content = "She used to disguise her staff as a bow to avoid being bothered by other mages. Like you, she prefers staying hidden.",
  ui_story_5088_50880801_7_dialog_content = "... Sorry for following you. I promise, my intentions are good. My name is Mithra Longinus, and I have a mission.",
  ui_story_5088_50880801_8_dialog_content = "A Longinus girl? A descendant of Anthony, I assume?",
  ui_story_5088_50880801_9_dialog_content = "You remember my forebear?",
  ui_story_5088_50880801_10_dialog_content = "Haha, he would always be keen to spend time with us creatures. We thought he was simply after some free food. Let me tell you, he left quite an impression on us.",
  ui_story_5088_50880801_11_dialog_content = "Now, after two thousand years, we meet another Longinus.",
  ui_story_5088_50880801_12_dialog_content = "Anthony... did he live a happy life?",
  ui_story_5088_50880801_13_dialog_content = "... He was very happy. After receiving Lord Achilles' blessing, he smiled and passed away. He was buried nearby with honor.",
  ui_story_5088_50880801_14_dialog_content = "To accomplish great deeds and leave this world in the embrace of loved ones... he was blessed.",
  ui_story_5088_50880801_15_dialog_content = "Two thousand years have passed, but we have finally received some good news.",
  ui_story_5088_50880801_16_dialog_content = "... Longinus, we can guess what this mission is that binds you.",
  ui_story_5088_50880801_17_dialog_content = "At this point, only you know that person's fate...",
  ui_story_5088_50880801_18_dialog_content = "But it seems as though you, like me, willingly embrace these shackles.",
  ui_story_5088_50880801_19_dialog_content = "If we request it, can you tell us?",
  ui_story_5088_50880801_20_dialog_content = "Our family's mission is to guard the secrets of the stars and not let anyone close to them.",
  ui_story_5088_50880801_21_dialog_content = "But if this is the command of the Star Warriors, I will speak of my mission.",
  ui_story_5088_50880801_22_dialog_content = "But before that, I just want to say... you've already helped me.",
  ui_story_5088_50880801_23_dialog_content = "Wow, you're awake!",
  ui_story_5088_50880801_24_dialog_content = "Those were just our clan's most trivial records. How much you have seen is due to your own conviction.",
  ui_story_5088_50880801_25_dialog_content = "Right... I saw the perseverance of the Longinus clan through the generations.",
  ui_story_5088_50880801_26_dialog_content = "... I think the best way to describe it would be \"unyielding to the last.\"",
  ui_story_5088_50880801_27_dialog_content = "And I'm not just talking about one person—this \"unyielding to the last\" thing applies to the whole Longinus clan.",
  ui_story_5088_50880801_28_dialog_content = "So I think the reason they all have such strong faith is even the reason you keep going to this day...",
  ui_story_5088_50880801_29_dialog_content = "It must be because Achilles is still around here somewhere.",
  ui_story_5088_50880801_30_dialog_content = "So you returned here to look for clues?",
  ui_story_5088_50880801_31_dialog_content = "Right, and I've already seen the final location. I want to see what Mr. Czerny left behind.",
  ui_story_5088_50880801_32_dialog_content = "Then what are we waiting for?",
  ui_story_5088_50880801_33_dialog_content = "Whoa! Friegson's so eager all of a sudden! Itching for a duel with Achilles, huh?",
  ui_story_5088_50880801_34_dialog_content = "... Enough prattle. Let's go.",
  ui_story_5088_50880801_35_dialog_content = "We're here.",
  ui_story_5088_50880801_36_dialog_content = "Hmm, at first glance, nothing stands out. And on closer inspection... still nothing.",
  ui_story_5088_50880801_37_dialog_content = "Yet, through the lens of magic, an intriguing colorless power is gathered here.",
  ui_story_5088_50880801_38_dialog_content = "Indeed. This is Achilles' magic formation.",
  ui_story_5088_50880801_39_dialog_content = "Can we force it open with our magic?",
  ui_story_5088_50880801_40_dialog_content = "It's worth a try.",
  ui_story_5088_50880801_41_dialog_content = "No... There's no need to go to such extreme lengths.",
  ui_story_5088_50880801_42_dialog_content = "Miss Mithra, please open the seal.",
  ui_story_5088_50880801_43_dialog_content = "You've got the key, right?",
  ui_story_5088_50880801_44_dialog_content = "...",
  ui_story_5088_50880801_45_dialog_content = "When my ancestor passed away, Lord Achilles gave our family an amulet.",
  ui_story_5088_50880801_46_dialog_content = "The Star Crest...",
  ui_story_5088_50880801_47_dialog_content = "A self-sustaining magic formation of the most delicate material—the highest honor Lord Achilles bestowed upon our clan.",
  ui_story_5088_50880801_48_dialog_content = "He probably intended for us to use this power to protect ourselves, but the Longinus family heads have always been reluctant to use it.",
  ui_story_5088_50880801_49_dialog_content = "It thus became a symbol of our vow, a family heirloom.",
  ui_story_5088_50880801_50_dialog_content = "I never thought it would one day be put to use.",
  ui_story_5088_50880801_51_dialog_content = "Will this violate your oath?",
  ui_story_5088_50880801_52_dialog_content = "No, because this is your wish and the original intention of the Longinus clan.",
  ui_story_5088_50880801_53_dialog_content = "... Thank you.",
  ui_story_5088_50880801_54_dialog_content = "No, Lady Friegson, please don't thank me...",
  ui_story_5088_50880801_55_dialog_content = "I never dreamt someone would protect us for two millennia.",
  ui_story_5088_50880801_56_dialog_content = "Mithra, for all this, please accept my gratitude.",
  ui_story_5088_50880801_57_dialog_content = "Otherwise, Friegson may feel somewhat ill at ease.",
  ui_story_5088_50880801_58_dialog_content = "I understand... Then, I will break the seal.",
  ui_story_5088_50880801_59_dialog_content = "<color=#e8d9bb>Mithra removes her necklace, revealing its true form—a Star Crest.</color>",
  ui_story_5088_50880801_60_dialog_content = "<color=#e8d9bb>Then, she summons a ray of radiance in the shape of a spear's tip from the Star Crest.</color>",
  ui_story_5088_50880801_61_dialog_content = "This is...",
  ui_story_5088_50880801_62_dialog_content = "Eraveil?",
  ui_story_5088_50880801_63_dialog_content = "H-How is this even possible?",
  ui_story_5088_50880801_64_dialog_content = "Wow, what beautiful plains... Look, Eraveil dandelions.",
  ui_story_5088_50880801_65_dialog_content = "Even the White Tower stands, restored in all its glory.",
  ui_story_5088_50880801_66_dialog_content = "It seems we must venture there to understand everything.",
  ui_story_5088_50880801_67_dialog_content = "However, it doesn't appear to be as serene as Eraveil once was.",
  ui_story_5088_50880801_68_dialog_content = "Huh? Are these...",
  ui_story_5088_50880802_1_dialog_content = "Could these be Achilles' defenses?",
  ui_story_5088_50880802_2_dialog_content = "Perhaps we should make our way to Obelisk of Return first.",
  ui_story_5088_50880802_3_dialog_content = "The nearer we draw, the stranger this feeling in my heart grows.",
  ui_story_5088_50880802_4_dialog_content = "Cynthia, Freya, do you feel it too?",
  ui_story_5088_50880802_5_dialog_content = "Could it still be the lingering influence of the magic formation?",
  ui_story_5088_50880802_6_dialog_content = "No, it feels like the crest is resonating.",
  ui_story_5088_50880802_7_dialog_content = "My sword... it seems to be speaking to me of... memories...",
  ui_story_5088_50880802_8_dialog_content = "?!",
  ui_story_5088_50880802_9_dialog_content = "It looks like we've found it.",
  ui_story_5088_50880802_10_dialog_content = "Verifying biological information, please wait.",
  ui_story_5088_50880802_11_dialog_content = "This is exactly what I saw once before...",
  ui_story_5088_50880802_12_dialog_content = "Caelestite detected, welcome to Wonderland.",
  ui_story_5088_50880802_13_dialog_content = "It seems our host is ready to welcome us.",
  ui_story_5088_50880802_14_dialog_content = "Now playing Czerny's last words. Please listen during your ascent.",
  ui_story_5088_50880802_15_dialog_content = "If you're listening to this, it means I succeeded, and a Caelestite of a new era has been guided here.",
  ui_story_5088_50880802_16_dialog_content = "Well done, hero from the future.",
  ui_story_5088_50880802_17_dialog_content = "To conserve this structure's remaining energy, I will be brief... In short, there is a damaged Colossus behind this tower.",
  ui_story_5088_50880802_18_dialog_content = "It was the vehicle Achilles and I used to come here...",
  ui_story_5088_50880802_19_dialog_content = "I never thought I would arrive here in my twilight years... the Colossus...",
  ui_story_5088_50880802_20_dialog_content = "Sorry, Master Czerny, please choose a Colossus quickly... I can't hold on much longer—everyone might soon discover you are here.",
  ui_story_5088_50880802_21_dialog_content = "Mantiz or 6#S%—you can choose either.",
  ui_story_5088_50880802_22_dialog_content = "No, I choose that one—Fortez!",
  ui_story_5088_50880802_23_dialog_content = "But that's the sealed <color=#FFB400>War Colossus</color>.",
  ui_story_5088_50880802_24_dialog_content = "Yes, that's exactly what I need.",
  ui_story_5088_50880802_25_dialog_content = "I researched for so long to find out why it was sealed. It... can generate Eclipsites. Perhaps our clan committed great sins in the past.",
  ui_story_5088_50880802_26_dialog_content = "But the Caelestites no longer need a War Colossus, so I might as well help destroy the last Eclipsite-generating device.",
  ui_story_5088_50880802_27_dialog_content = "Then please, Master, take it away.",
  ui_story_5088_50880802_28_dialog_content = "Fortez, heed my call, accept my command, let me navigate you... Hmm?",
  ui_story_5088_50880802_29_dialog_content = "It is devoid of consciousness?",
  ui_story_5088_50880802_30_dialog_content = "How can that be? Could it be that when it was sealed, its consciousness was deliberately erased?",
  ui_story_5088_50880802_31_dialog_content = "It's very likely. The War Colossi would not obey us, the traitors who turned our backs on the war. Perhaps it is merely our prisoner now.",
  ui_story_5088_50880802_32_dialog_content = "Then, I shall be the one to navigate you!",
  ui_story_5088_50880802_33_dialog_content = "Master Czerny... will you return?",
  ui_story_5088_50880802_34_dialog_content = "Hahaha, yes! One day, I will return to face my punishment.",
  ui_story_5088_50880802_35_dialog_content = "No matter how long it takes, I will strive to return.",
  ui_story_5088_50880802_36_dialog_content = "If you can't wait for me, play my music at Windelion to guide me back.",
  ui_story_5088_50880802_37_dialog_content = "Master Czerny...",
  ui_story_5088_50880802_38_dialog_content = "\"Do not go gentle into that good night.\"",
  ui_story_5088_50880802_39_dialog_content = "\"Old age should burn and rave at the close of day.\"",
  ui_story_5088_50880802_40_dialog_content = "\"Rage, rage against the dying of the light...\"",
  ui_story_5088_50880802_41_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5088_50880802_42_dialog_content = "?!",
  ui_story_5088_50880802_43_dialog_content = "I'm back, Achilles... I accidentally made a rather sizeable hole. Sorry...",
  ui_story_5088_50880802_44_dialog_content = "You... What's going on here?",
  ui_story_5088_50880802_45_dialog_content = "This Colossus can use your genetic information to create a new body.",
  ui_story_5088_50880802_46_dialog_content = "I say create, but it's just copying or using the term designated by the control device—\"cloning.\"",
  ui_story_5088_50880802_47_dialog_content = "This way, your consciousness won't be rejected.",
  ui_story_5088_50880802_48_dialog_content = "However, creating a new body takes time, and I can't ensure the new body won't face erosion. Further observation may be required.",
  ui_story_5088_50880802_49_dialog_content = "The Colossus is too conspicuous to remain here. I must first gather your consciousness using the Echo Template I brought to house you.",
  ui_story_5088_50880802_50_dialog_content = "If I were to ask if you're capable of actually succeeding in all this, it might seem as though I don't trust you.",
  ui_story_5088_50880802_51_dialog_content = "But... have you confirmed our doubts?",
  ui_story_5088_50880802_52_dialog_content = "Does one's consciousness equate to one's soul?",
  ui_story_5088_50880802_53_dialog_content = "Memory, thought, nature—together, they form my being.",
  ui_story_5088_50880802_54_dialog_content = "Is this consciousness my soul?",
  ui_story_5088_50880802_55_dialog_content = "I have tested the theory.",
  ui_story_5088_50880802_56_dialog_content = "You... Czerny, what have you done?!",
  ui_story_5088_50880802_57_dialog_content = "I have abandoned my body and stored my consciousness here.",
  ui_story_5088_50880802_58_dialog_content = "In Fortez.",
  ui_story_5088_50880802_59_dialog_content = "?!",
  ui_story_5088_50880802_60_dialog_content = "To confirm every speculation we held, I conducted this experiment—after all, I am but an old man.",
  ui_story_5088_50880802_61_dialog_content = "The answer is, my soul remains steadfast, still eager to help you.",
  ui_story_5088_50880802_62_dialog_content = "Czerny...",
  ui_story_5088_50880802_63_dialog_content = "Now I am no longer a Caelestite, and am unable to fully utilize my psychic abilities.",
  ui_story_5088_50880802_64_dialog_content = "But fortunately, you are skilled in sealing and conjuring magic formations.",
  ui_story_5088_50880802_65_dialog_content = "I will help transfer your consciousness into the Colossus' Echo Template.",
  ui_story_5088_50880802_66_dialog_content = "Then... we shall fly to Eraveil!",
  ui_story_5088_50880802_67_dialog_content = "Even if our voices cannot reach them, someday, someone will be guided to us and unseal us.",
  ui_story_5088_50880802_68_dialog_content = "... I now understand your resolve.",
  ui_story_5088_50880802_69_dialog_content = "In this final moment, I feel myself compelled to leave something behind.",
  ui_story_5088_50880901_1_dialog_content = "<color=#e8d9bb>Click! The energy flow within the White Tower suddenly cuts off, and Czerny's words fade away.</color>",
  ui_story_5088_50880901_2_dialog_content = "I'll go to the center and take a look.",
  ui_story_5088_50880901_3_dialog_content = "How do you plan on getting there? It's very dangerous.",
  ui_story_5088_50880901_4_dialog_content = "<color=#e8d9bb>Mithra doesn't answer and simply spreads her wings. Her wings have been waiting all along, hidden beneath her modest cloak.</color>",
  ui_story_5088_50880901_5_dialog_content = "So, all we need to do is fly up... Oh, I almost forgot—she's from the Courier Union.",
  ui_story_5088_50880901_6_dialog_content = "Those who hide more often than not need to suppress themselves without compromise. Her wings seem to be proof of this fact.",
  ui_story_5088_50880901_7_dialog_content = "Can you manage by yourself? Do you need my help—I'm good with lightning...",
  ui_story_5088_50880901_8_dialog_content = "I've found the faulty line. Just wait down below.",
  ui_story_5088_50880901_9_dialog_content = "I've done countless jobs like this before, so there's nothing to worry about.",
  ui_story_5088_50880901_10_dialog_content = "If you don't keep an eye on her, it's like she vanishes from the story altogether.",
  ui_story_5088_50880901_11_dialog_content = "Should we do the same?",
  ui_story_5088_50880901_12_dialog_content = "No, that won't be necessary. I'm used to hiding on the fringes of a tale—the less noticeable, the better.",
  ui_story_5088_50880901_13_dialog_content = "Our clan has lived this way for generations. We don't stay in one place, and we don't make friends.",
  ui_story_5088_50880901_14_dialog_content = "We wish only to become the night that guards the stars.",
  ui_story_5088_50880901_15_dialog_content = "You might be used to slipping into the shadows, blending into the foliage...",
  ui_story_5088_50880901_16_dialog_content = "But, Miss Mithra... I don't think you were born just to fulfill other people's happiness. You deserve happiness of your own too.",
  ui_story_5088_50880901_17_dialog_content = "...",
  ui_story_5088_50880901_18_dialog_content = "The people of your clan have silently sacrificed themselves for two thousand years. We owe you more than words can express.",
  ui_story_5088_50880901_19_dialog_content = "Please don't say that... I'm nothing compared to my ancestors...",
  ui_story_5088_50880901_20_dialog_content = "I've been afraid, angry, confused, and I even thought of giving up...",
  ui_story_5088_50880901_21_dialog_content = "I spent over a decade searching for Caelestites, but there was no one left. The pain was unbearable.",
  ui_story_5088_50880901_22_dialog_content = "I was so terrified, fearing I would fail entirely...",
  ui_story_5088_50880901_23_dialog_content = "But, a hero is someone who knows fear and stands tall nonetheless.",
  ui_story_5088_50880901_24_dialog_content = "Huh?!",
  ui_story_5088_50880901_25_dialog_content = "This is the most valuable lesson I learned from my dearest Marcela.",
  ui_story_5088_50880901_26_dialog_content = "Mithra Longinus, lift your head. You have no cause to feel ashamed. It was never fair for your clan to bear such a heavy burden for two thousand years.",
  ui_story_5088_50880901_27_dialog_content = "Remember, you are worthy of our respect, as is your great ancestor.",
  ui_story_5088_50880901_28_dialog_content = "Adras...?",
  ui_story_5088_50880901_29_dialog_content = "We are all the same, aren't we? Lost for too long...",
  ui_story_5088_50880901_30_dialog_content = "Uh-oh, is the vice-captain seeing things again?",
  ui_story_5088_50880901_31_dialog_content = "Huh? Why did I suddenly remember that?",
  ui_story_5088_50880901_32_dialog_content = "It seems the final chapter of the story is ready to be unveiled.",
  ui_story_5088_50880901_33_dialog_content = "Is it because of these crests? They've been resonating like crazy since we got here.",
  ui_story_5088_50880901_34_dialog_content = "The thaw in our hearts is beginning to melt away...",
  ui_story_5088_50880901_35_dialog_content = "The line is fixed.",
  ui_story_5088_50880901_36_dialog_content = "It seems we have all found our way.",
  ui_story_5088_50880901_37_dialog_content = "There's no need to worry, everyone.",
  ui_story_5088_50880901_38_dialog_content = "I... yes... I still cannot accept Marcela's departure, so she remains by my side, guarding me.",
  ui_story_5088_50880901_39_dialog_content = "If one day I could rest with her till the end of time, that would be truly wonderful, but until then, I wish to protect this world and journey with you all once more.",
  ui_story_5088_50880901_40_dialog_content = "Will you continue to walk this path with me?",
  ui_story_5088_50880901_41_dialog_content = "... Do you even need to ask?",
  ui_story_5088_50880901_42_dialog_content = "Onward!",
  ui_story_5088_50880901_43_dialog_content = "Thank you, Mithra.",
  ui_story_5088_50880901_44_dialog_content = "You don't need to thank me... I should be the one thanking you.",
  ui_story_5088_50880901_45_dialog_content = "It is due to your efforts that the Star Warriors will shine again, and I can finally see some hope for the future.",
  ui_story_5088_50880901_46_dialog_content = "You're playing a kind of minor part right now. If you were as full of pluck as I am and had more lines, your overall presence might start to take off!",
  ui_story_5088_50880901_47_dialog_content = "... Your cheerfulness is a bit over the top.",
  ui_story_5088_50880901_48_dialog_content = "In two thousand years, we have only seen two Caelestites.",
  ui_story_5088_50880901_49_dialog_content = "Both she and PlayerName are our benefactors, sharing nothing but goodwill.",
  ui_story_5088_50880901_50_dialog_content = "It's such a shame...",
  ui_story_5088_50880901_51_dialog_content = "...",
  ui_story_5088_50880901_52_dialog_content = "<size=30>Sigh, what a smooth talker...</size> Wow, look at that rock! It's a rock and it's so... rocky... and there are enemies!",
  ui_story_5088_50880901_53_dialog_content = "<size=45>Seriously! Heads up, enemies are coming!</size>",
  ui_story_5088_50880902_1_dialog_content = "Is that all?",
  ui_story_5088_50880902_2_dialog_content = "I have left my final obsession with the self-circulating magic formation in this body.",
  ui_story_5088_50880902_3_dialog_content = "As long as my flesh exists, the formation will persist. I will forever watch over this place.",
  ui_story_5088_50880902_4_dialog_content = "Give that to me. Let me upload the consciousness.",
  ui_story_5088_50880902_5_dialog_content = "Roar!!!",
  ui_story_5088_50880902_6_dialog_content = "Magic of the forest, hide us from the eyes of our pursuer—Go!",
  ui_story_5088_50880902_7_dialog_content = "No! I won't let you leave!",
  ui_story_5088_50880902_8_dialog_content = "<size=45>Death to all enemies!!!</size>",
  ui_story_5088_50880902_9_dialog_content = "A Caelestite... I must spare him...",
  ui_story_5088_50880902_10_dialog_content = "<color=#e8d9bb>Silently, he watches as his quarry escapes.</color>",
  ui_story_5088_50880902_11_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50881000_1_dialog_content = "... But our journey is not complete.",
  ui_story_5088_50881000_2_dialog_content = "What happened? Why did it stop here?",
  ui_story_5088_50881000_3_dialog_content = "PlayerName, you know this is just a message, right?",
  ui_story_5088_50881000_4_dialog_content = "Uh...",
  ui_story_5088_50881000_5_dialog_content = "I was careless.",
  ui_story_5088_50881000_6_dialog_content = "I didn't know that once the generation device was activated, the strong signal it emitted would attract...",
  ui_story_5088_50881000_7_dialog_content = "Them.",
  ui_story_5088_50881000_8_dialog_content = "Here, over here, over here, over here...",
  ui_story_5088_50881000_9_dialog_content = "How could so many Eclipsites catch up with us?",
  ui_story_5088_50881000_10_dialog_content = "Could it be that they tracked the \"X substance\" signal from the device? Curse their dark power!",
  ui_story_5088_50881000_11_dialog_content = "...",
  ui_story_5088_50881000_12_dialog_content = "Oh no, Achilles' consciousness hasn't fused with the new body yet. He can't fight.",
  ui_story_5088_50881000_13_dialog_content = "<size=45>Wings hit...! We're done for!</size>",
  ui_story_5088_50881000_14_dialog_content = "<color=#FFB400>Dark starlight! Erupt!</color>",
  ui_story_5088_50881000_15_dialog_content = "What's going on?",
  ui_story_5088_50881000_16_dialog_content = "A massive amount of essence power... \"N substance\" converged...",
  ui_story_5088_50881000_17_dialog_content = "Achilles, is that you?",
  ui_story_5088_50881000_18_dialog_content = "... Can you hear me?",
  ui_story_5088_50881000_19_dialog_content = "You can remotely control your new body... It's a miracle...",
  ui_story_5088_50881000_20_dialog_content = "I... can't... sustain it...",
  ui_story_5088_50881000_21_dialog_content = "I've crashed... We can't continue flying...",
  ui_story_5088_50881000_22_dialog_content = "I'll try to repair myself with the fireflies, but before that... can you use your magic to create an illusion?",
  ui_story_5088_50881000_23_dialog_content = "... I'll... try...",
  ui_story_5088_50881000_24_dialog_content = "But, my repairs failed.",
  ui_story_5088_50881000_25_dialog_content = "I had the fireflies use the nearby materials available to create this <color=#FFB400>Obelisk of Return</color> so that I could leave a message.",
  ui_story_5088_50881000_26_dialog_content = "I wanted to include the genetic information of the Longinus clan in the identification system, but there was no one from the Longinus family to gather it from.",
  ui_story_5088_50881000_27_dialog_content = "So, I extracted the racial information of the Caelestites from my own corpse as the only key.",
  ui_story_5088_50881000_28_dialog_content = "Before the energy ran out, I witnessed the Longinus clan find this place.",
  ui_story_5088_50881000_29_dialog_content = "But they didn't seem to understand what had happened, and perhaps due to the Eclipsite-generating device, they didn't dare inform Eraveil.",
  ui_story_5088_50881000_30_dialog_content = "All I could do was wait... wait for your arrival... once I shut down, my consciousness will disappear... so I left you these words...",
  ui_story_5088_50881000_31_dialog_content = "Ludweiss and Achilles are at the top of this tower, and the new body is still in the Colossus' hibernation pod.",
  ui_story_5088_50881000_32_dialog_content = "Please go up and see them first...",
  ui_story_5088_50881000_33_dialog_content = "... It looks like your clan was worrying about things going south again, so they stuck fast to their duty.",
  ui_story_5088_50881000_34_dialog_content = "And for two thousand years, your people chose to stay hidden, silently watching over those journals, waiting for the prophecy...",
  ui_story_5088_50881000_35_dialog_content = "Yes.",
  ui_story_5088_50881000_36_dialog_content = "The crest I hold, imbued with Lord Achilles' power, allows each family head to add a portion of their memories and will to it.",
  ui_story_5088_50881000_37_dialog_content = "I've witnessed my ancestors' efforts—they created an ecosystem within this magic formation and maintained the Colossus.",
  ui_story_5088_50881000_38_dialog_content = "They hoped this place would become a worthy resting place.",
  ui_story_5088_50881000_39_dialog_content = "Later, the Colossus was repaired and its energy supply was restored, but no one dared to touch it. In my generation, we didn't even know its exact location.",
  ui_story_5088_50881000_40_dialog_content = " Czerny, wait for me in there...",
  ui_story_5088_50881000_41_dialog_content = "I've been through this before—I once found part of a friend's consciousness in a War Colossus.",
  ui_story_5088_50881000_42_dialog_content = "Even after hearing all this, we still don't understand some things.",
  ui_story_5088_50881000_43_dialog_content = "Once this is over, please tell us everything you know.",
  ui_story_5088_50881000_44_dialog_content = "Perhaps, Achilles himself can tell you.",
  ui_story_5088_50881000_45_dialog_content = "You're quite confident about all this, aren't you? Fine! I'll put my faith in that radiant hope shining in your eyes!",
  ui_story_5088_50881000_46_dialog_content = "Because last time, we actually achieved the perfect ending we were after...",
  ui_story_5088_50881000_47_dialog_content = "Then let's do it again!",
  ui_story_5088_50881000_48_dialog_content = "Yes... a perfect ending... one more time!",
  ui_story_5088_50881102_1_dialog_content = "This is where Achilles' consciousness now resides...",
  ui_story_5088_50881102_2_dialog_content = "Only you can merge Lord Achilles' consciousness with his body.",
  ui_story_5088_50881102_3_dialog_content = "I'll do my best.",
  ui_story_5088_50881102_4_dialog_content = "...",
  ui_story_5088_50881102_5_dialog_content = "You're... here...",
  ui_story_5088_50881102_6_dialog_content = "Hmm?",
  ui_story_5088_50881102_7_dialog_content = "...",
  ui_story_5088_50881102_8_dialog_content = "Thank you for leading us out of two thousand years of darkness.",
  ui_story_5088_50881102_9_dialog_content = "It's time for us to take her back.",
  ui_story_5088_50881102_10_dialog_content = "Ludweiss...",
  ui_story_5088_50881102_11_dialog_content = "Finally, we are reunited.",
  ui_story_5088_50881102_12_dialog_content = "PlayerName, we'd like to stay here a little longer.",
  ui_story_5088_50881102_13_dialog_content = "You go ahead to the Colossus first.",
  ui_story_5088_50881102_14_dialog_content = "Sure...",
  ui_story_5088_50881102_15_dialog_content = "Let's go. I'll protect you.",
  ui_story_5088_50881102_16_dialog_content = "Will this time be like a dream for Lord Achilles?",
  ui_story_5088_50881102_17_dialog_content = "For him, this loss lasts so long.",
  ui_story_5088_50881102_18_dialog_content = "But I think he'll still smile.",
  ui_story_5088_50881102_19_dialog_content = "Because the Achilles I know is a pioneer, one who always moves forward without fear.",
  ui_story_5088_50881102_20_dialog_content = "I know... he'll definitely keep going.",
  ui_story_5088_50881102_21_dialog_content = "Is this... the philosophy of Windelion?",
  ui_story_5088_50881102_22_dialog_content = "Yeah...",
  ui_story_5088_50881102_23_dialog_content = "Remember the departed, and send them your thoughts, but at the same time, keep moving forward.",
  ui_story_5088_50881102_24_dialog_content = "...",
  ui_story_5088_50881102_25_dialog_content = "We're here.",
  ui_story_5088_50881102_26_dialog_content = "<color=#e8d9bb>In the depths of the broken-down Colossus stands a piano-like control panel—one the Caelestite knows so well.</color>",
  ui_story_5088_50881102_27_dialog_content = "<color=#e8d9bb>And waiting in that seat, there is a skeleton.</color>",
  ui_story_5088_50881102_28_dialog_content = "Mr. Czerny...",
  ui_story_5088_50881102_29_dialog_content = "...",
  ui_story_5088_50881102_30_dialog_content = "...",
  ui_story_5088_50881102_31_dialog_content = "Achilles' body rests here.",
  ui_story_5088_50881102_32_dialog_content = "Time to begin my work.",
  ui_story_5088_50881102_33_dialog_content = "<color=#e8d9bb>I carefully move Mr. Czerny, handing him to Mithra, and then, with great respect... I press the keys.</color>",
  ui_story_5088_50881102_34_dialog_content = "The Colossus has been reawakened. It seems the time has come.",
  ui_story_5088_50881102_35_dialog_content = "If you're hearing this message, it means the self-verification program has been executed successfully and Achilles' body is finally stable.",
  ui_story_5088_50881102_36_dialog_content = "Next, you must choose whether to complete this great feat.",
  ui_story_5088_50881102_37_dialog_content = "But this is an extremely dangerous task, one that could very well cost you your life. If you choose to decline it, we will not blame you.",
  ui_story_5088_50881102_38_dialog_content = "But if you are indeed one brave enough to accept this responsibility, I offer you my deepest gratitude.",
  ui_story_5088_50881102_39_dialog_content = "Listen well—colorless power is the essence of Lumina.",
  ui_story_5088_50881102_40_dialog_content = "According to my research, this is the elusive \"N substance.\" Unfortunately, I no longer have time to investigate its connection with \"X substance.\"",
  ui_story_5088_50881102_41_dialog_content = "The essence of colorless power and colored Lumina is fundamentally the same, but our innate nature makes it difficult for us to recognize the essence of the colorless variety.",
  ui_story_5088_50881102_42_dialog_content = "Fortunately, Achilles' body is no longer entangled in dark power, reducing the danger.",
  ui_story_5088_50881102_43_dialog_content = "However, you will still face great risks when guiding his consciousness through the colorless barrier.",
  ui_story_5088_50881102_44_dialog_content = "If you are ready, place the Echo Template here and begin the guidance process.",
  ui_story_5088_50881102_45_dialog_content = "System recording ended—",
  ui_story_5088_50881102_46_dialog_content = "I'm ready, Mr. Czerny.",
  ui_story_5088_50881102_47_dialog_content = "Mithra, while I'm using my psychic abilities, I'll be counting on you to take care of everything else.",
  ui_story_5088_50881102_48_dialog_content = "I'll protect you. I swear it.",
  ui_story_5088_50881102_49_option_content = "The last psychic scan",
  ui_story_5088_50881102_50_dialog_content = "Achilles, your long dream can finally come to an end.",
  ui_story_5088_50881102_51_dialog_content = "Please return with me to...",
  ui_story_5088_50881102_52_dialog_content = "...",
  ui_story_5088_50881102_53_dialog_content = "It really is dangerous here. I can't see a thing...",
  ui_story_5088_50881102_54_dialog_content = "Here, over here, over here, over here...",
  ui_story_5088_50881102_55_dialog_content = "What is that? This voice sounds so familiar...",
  ui_story_5088_50881102_56_dialog_content = "... Another \"traitor.\"",
  ui_story_5088_50881102_57_dialog_content = "Thanks to you restarting me, I shall finally be revived.",
  ui_story_5088_50881102_58_dialog_content = "Are you... this Colossus?",
  ui_story_5088_50881102_59_dialog_content = "But Mr. Czerny didn't find a consciousness inside you...",
  ui_story_5088_50881102_60_dialog_content = "Fool! I hid when you traitors caught me. Why would I show myself so carelessly?",
  ui_story_5088_50881102_61_dialog_content = "Thank you for returning me to my body.",
  ui_story_5088_50881102_62_dialog_content = "I see... you didn't store your consciousness in the machine components... you transferred it to a backup template!",
  ui_story_5088_50881102_63_dialog_content = "You're quite a clever one.",
  ui_story_5088_50881102_64_dialog_content = "Yes. This traitor and I share the same Echo Template.",
  ui_story_5088_50881102_65_dialog_content = "Now, you shall help me revive!",
  ui_story_5088_50881102_66_dialog_content = "(My head... hurts so much...)",
  ui_story_5088_50881102_67_dialog_content = "(Is it infiltrating my mind? How can a Colossus' consciousness even do something like this?)",
  ui_story_5088_50881102_68_dialog_content = "Don't forget, you're connected to my operating system.",
  ui_story_5088_50881102_69_dialog_content = "(No, I can't let it...)",
  ui_story_5088_50881102_70_dialog_content = "Now you're mine!",
  ui_story_5088_50881102_71_dialog_content = "Urghhh...",
  ui_story_5088_50881102_72_dialog_content = "<size=45>Annihilation!</size>",
  ui_story_5088_50881102_73_dialog_content = "Aaaahhhhh!",
  ui_story_5088_50881102_74_dialog_content = "<color=#e8d9bb>Claymore's dormant body suddenly awakens, unleashing a mighty burst of sword energy toward the ground.</color>",
  ui_story_5088_50881102_75_dialog_content = "<color=#e8d9bb>With just one strike, Fortez is cleaved in half.</color>",
  ui_story_5088_50881102_76_dialog_content = "<color=#e8d9bb>From the Eclipsite-generating device to its body, from its menacing broken wings to its ambitions, all are obliterated in one blow.</color>",
  ui_story_5088_50881102_77_dialog_content = "PlayerName!",
  ui_story_5088_50881102_78_dialog_content = "My connection was cut... Achilles saved me.",
  ui_story_5088_50881102_79_dialog_content = "No! But what about you, Achilles?!",
  ui_story_5088_50881102_80_dialog_content = "The Colossus is collapsing. It's ruined.",
  ui_story_5088_50881102_81_dialog_content = "No! I need to complete the fusion before it breaks down completely!",
  ui_story_5088_50881102_82_option_content = "Force Boost!",
  ui_story_5088_50881102_83_dialog_content = "Fool! After narrowly escaping, you still dare to come back here?",
  ui_story_5088_50881102_84_dialog_content = "What else did you expect?",
  ui_story_5088_50881102_85_dialog_content = "I promised everyone I'd bring Achilles back.",
  ui_story_5088_50881102_86_dialog_content = "Then, I'll tell him that spring has arrived.",
  ui_story_5088_50881102_87_dialog_content = "I'll take him, Mr. Czerny, and Lady Ludweiss to Eraveil...",
  ui_story_5088_50881102_88_dialog_content = "To see the dandelion lanterns and colorful Windelion dolls with everyone!",
  ui_story_5088_50881102_89_dialog_content = "I will never let Achilles become just a memory!!!",
  ui_story_5088_50881201_1_dialog_content = "Come on out, my defenders!",
  ui_story_5088_50881201_2_dialog_content = "Monsters? No, are they being created by that generation device?",
  ui_story_5088_50881201_3_dialog_content = "I won't let you hurt PlayerName!",
  ui_story_5088_50881201_4_dialog_content = "(Quick, I need to get through this colorless storm...)",
  ui_story_5088_50881201_5_dialog_content = "Achilles, where are you?",
  ui_story_5088_50881201_6_dialog_content = "Let me be your beacon! Come with me and return to your body!",
  ui_story_5088_50881201_7_dialog_content = "Think again! My body's already gone... now his body will be mine!",
  ui_story_5088_50881201_8_dialog_content = "Urgh...",
  ui_story_5088_50881201_9_dialog_content = "A fallen Colossus that bows to the Eclipse will never defeat a Caelestite's psychic abilities!",
  ui_story_5088_50881201_10_dialog_content = "je^&c—",
  ui_story_5088_50881201_11_dialog_content = "Where did you get this power from?",
  ui_story_5088_50881201_12_dialog_content = "I've fought countless enemies tougher than you! You'll never take me down!",
  ui_story_5088_50881201_13_dialog_content = "... Surely you cannot handle this power! Your body can't take such strain!",
  ui_story_5088_50881201_14_dialog_content = "Look, the energy field is out of control. You'll never find the one you wish to help in this storm.",
  ui_story_5088_50881201_15_dialog_content = "He's a colorless existence! How will you discern his aura? With those eyes of yours that are only drawn to light?",
  ui_story_5088_50881201_16_dialog_content = "I... I'm done listening to your nonsense!!!",
  ui_story_5088_50881201_17_dialog_content = "<size=45>Hyaaaa!</size>",
  ui_story_5088_50881201_18_dialog_content = "No...",
  ui_story_5088_50881201_19_dialog_content = "(All the fatigue from these past few days is catching up with me... My head feels like it's gonna explode... like I'm being pulled down...)",
  ui_story_5088_50881201_20_dialog_content = "(I can't fall now... I can't give up...)",
  ui_story_5088_50881201_21_dialog_content = "(But... I'm so tired... and this pain... I feel like I'm at my limit...)",
  ui_story_5088_50881201_22_dialog_content = "Achilles... Where are you...?",
  ui_story_5088_50881201_23_dialog_content = "When hard work can't get the job done, you have to rely on your luck and intuition.",
  ui_story_5088_50881201_24_dialog_content = "(Why did that just pop into my head all of a sudden...?)",
  ui_story_5088_50881201_25_dialog_content = "(Argh! Where did this fire come from in this sea of chaos... Huh?)",
  ui_story_5088_50881201_26_dialog_content = "<color=#e8d9bb>In my final moments of confusion, I'm suddenly awakened by flames.</color>",
  ui_story_5088_50881201_27_dialog_content = "<color=#e8d9bb>The source of the fire is the two Star Crests Casta helped me find.</color>",
  ui_story_5088_50881201_28_dialog_content = "This one is Ludweiss', and the other should be... Huh?",
  ui_story_5088_50881201_29_dialog_content = "Gaze up at the sky, and the stars will shine in response.",
  ui_story_5088_50881201_30_dialog_content = "The warmth of their light is still the same, even after two thousand years.",
  ui_story_5088_50881201_31_dialog_content = "This time, let us help you!",
  ui_story_5088_50881201_32_dialog_content = "Lady Ludweiss? Mr. Czerny?",
  ui_story_5088_50881201_33_dialog_content = "Could it be that within the crests also lie your...",
  ui_story_5088_50881201_34_dialog_content = "<color=#FFB400>Our hopes and thoughts!</color>",
  ui_story_5088_50881201_35_dialog_content = "Where did you come from?! What are you trying to pull?",
  ui_story_5088_50881201_36_dialog_content = "Us? Hah! We have traversed two millennia—",
  ui_story_5088_50881201_37_dialog_content = "Passed down through the ages—",
  ui_story_5088_50881201_38_dialog_content = "A miracle born of the deepest connections!",
  ui_story_5088_50881201_39_dialog_content = "Someone like you, who only incites conflict and hinders heartfelt bonds...",
  ui_story_5088_50881201_40_dialog_content = "How could you ever possibly understand?!",
  ui_story_5088_50881201_41_dialog_content = "Achilles! You've slept enough! Wake up!!!",
  ui_story_5088_50881201_42_dialog_content = "... Ludweiss?",
  ui_story_5088_50881201_43_dialog_content = "No, no! That's my body!!!",
  ui_story_5088_50881201_44_dialog_content = "Watch out, it's about to attack!",
  ui_story_5088_50881201_45_dialog_content = "Let me cover the defense!",
  ui_story_5088_50881201_46_dialog_content = "Young traitor, do you think they can truly protect you? You're too weak...",
  ui_story_5088_50881201_47_dialog_content = "Little brother from the future!",
  ui_story_5088_50881201_48_dialog_content = "You once told me that you believe memories are a curse.",
  ui_story_5088_50881201_49_dialog_content = "But having lived out my life, I have something to share with you.",
  ui_story_5088_50881201_50_dialog_content = "To me, <color=#FFB400>memories are gifts</color>! You've received many gifts, and you've honored those myriad thoughts. That is something truly remarkable.",
  ui_story_5088_50881201_51_dialog_content = "That's right.",
  ui_story_5088_50881201_52_dialog_content = "You've inherited our memories and will, and you made it here. That alone is incredible.",
  ui_story_5088_50881201_53_dialog_content = "Your actions prove that the torch of heroism can be carried from one age to the next.",
  ui_story_5088_50881201_54_dialog_content = "Now, it's time for the heroes of old to realize their joy.",
  ui_story_5088_50881201_55_dialog_content = "So, don't be afraid, and don't be confused...",
  ui_story_5088_50881201_56_dialog_content = "Stand tall, and deliver the final blow.",
  ui_story_5088_50881201_57_dialog_content = "Alright!",
  ui_story_5088_50881201_58_dialog_content = "Silent Hunters!",
  ui_story_5088_50881201_59_dialog_content = "<color=#FFB400>Engage!</color>",
  ui_story_5088_50881201_60_dialog_content = "What is this...? More troublesome foes...",
  ui_story_5088_50881201_61_dialog_content = "Fortez... don't you dare look away... you still have to...",
  ui_story_5088_50881201_62_dialog_content = "You little brat...",
  ui_story_5088_50881201_63_dialog_content = "Get...",
  ui_story_5088_50881201_64_dialog_content = "... the hell out of this world!",
  ui_story_5088_50881201_65_dialog_content = "No, no, no, no!",
  ui_story_5088_50881201_66_dialog_content = "<size=45>I see it, colorless wavelength!</size>",
  ui_story_5088_50881201_67_dialog_content = "Achilles!",
  ui_story_5088_50881202_1_dialog_content = "PlayerName is bleeding badly! We need to find a way to stop it...",
  ui_story_5088_50881202_2_dialog_content = "No, let me take care of it this time.",
  ui_story_5088_50881202_3_dialog_content = "We can't disturb him now. All we can do is use magic to stop the bleeding.",
  ui_story_5088_50881202_4_dialog_content = "Fortez's consciousness is gone, and Achilles' consciousness has successfully returned... Ludweiss, we did it...",
  ui_story_5088_50881202_5_dialog_content = "It seems the time to say goodbye has truly arrived.",
  ui_story_5088_50881202_6_dialog_content = "But...",
  ui_story_5088_50881202_7_dialog_content = "I finally got to see all of you...",
  ui_story_5088_50881202_8_dialog_content = "True.",
  ui_story_5088_50881202_9_dialog_content = "Well now, I made up my mind quite a while ago that it's only right for me to give you a gift—for all your hard work, of course.",
  ui_story_5088_50881202_10_dialog_content = "I hope you will like it.",
  ui_story_5088_50881202_11_dialog_content = "This is the last thing I can accomplish with the remaining energy...",
  ui_story_5088_50881202_12_dialog_content = "Ah, by the way, could you tell us your name?",
  ui_story_5088_50881202_13_dialog_content = "My name is PlayerName... I'm... a Caelestite. I work with my friends in logistics.",
  ui_story_5088_50881202_14_dialog_content = "You're a very kind and remarkable soul—a truly glorious hero of your age.",
  ui_story_5088_50881202_15_dialog_content = "Thank you.",
  ui_story_5088_50881202_16_dialog_content = "I... um... I...",
  ui_story_5088_50881202_17_dialog_content = "Please take us back to Eraveil.",
  ui_story_5088_50881202_18_dialog_content = "Wipe away your tears, and give a smile for Windelion.",
  ui_story_5088_50881202_19_dialog_content = "Your thoughts have already reached us... on the river where we gather.",
  ui_story_5088_50881202_20_dialog_content = "You will never be alone.",
  ui_story_5088_50881202_21_dialog_content = "Farewell.",
  ui_story_5088_50881202_22_dialog_content = "Wake up... Wake up...",
  ui_story_5088_50881202_23_dialog_content = "I... Where are they...? What happened...?",
  ui_story_5088_50881202_24_dialog_content = "After the magic formation outside disappeared, some curious children from a nearby village crept in.",
  ui_story_5088_50881202_25_dialog_content = "The Star Warriors departed to keep them safe.",
  ui_story_5088_50881202_26_dialog_content = "But... I think they might be unsure of how to approach Lord Achilles.",
  ui_story_5088_50881202_27_dialog_content = "This is... the Echo Template...",
  ui_story_5088_50881202_28_dialog_content = "Oh, another one is broken.",
  ui_story_5088_50881202_29_dialog_content = "But luckily, I managed to save the consciousness inside this time...",
  ui_story_5088_50881202_30_dialog_content = "... Let's head out for now. Things might get awkward if Achilles' first sight is a total stranger when he wakes up.",
  ui_story_5088_50881202_31_dialog_content = "Come on, let me help you out of here.",
  ui_story_5088_50881202_32_dialog_content = "It's so beautiful...",
  ui_story_5088_50881202_33_dialog_content = "Sadly, once Lord Achilles' magic formation is lifted, this place may soon revert to the normal wilds of Northland.",
  ui_story_5088_50881202_34_dialog_content = "But that's okay... A lot of things are best preserved in memories.",
  ui_story_5088_50881202_35_dialog_content = "...",
  ui_story_5088_50881202_36_dialog_content = "Please, take this.",
  ui_story_5088_50881202_37_dialog_content = "What is this?",
  ui_story_5088_50881202_38_dialog_content = "It's the final entry in my journal—a token of the Longinus clan's gratitude, granted only to those who complete a true hero's journey.",
  ui_story_5088_50881202_39_dialog_content = "... Huh?",
  ui_story_5088_50881202_40_dialog_content = "<color=#e8d9bb>A wind rises beneath the distant White Tower, ascending to the sky.</color>",
  ui_story_5088_50881202_41_dialog_content = "<color=#e8d9bb>A gentle, melodious tune begins to play alongside the breeze.</color>",
  ui_story_5088_50881202_42_dialog_content = "<color=#e8d9bb>The White Tower, designed by musical maestro Czerny, is itself an instrument.</color>",
  ui_story_5088_50881202_43_dialog_content = "<color=#e8d9bb>And it plays a lullaby once known throughout Eraveil.</color>",
  ui_story_5088_50881202_44_dialog_content = "<color=#e8d9bb>Composed by Czerny under Ludweiss' guidance—</color><color=#FFB400>Windelion Day: A Lullaby for Travelers.</color>",
  ui_story_5088_50881202_45_dialog_content = "It's simply divine.",
  ui_story_5088_50881202_46_dialog_content = "This is the <color=#FFB400>gift</color>...",
  ui_story_5088_50881202_47_dialog_content = "Thank you. Thank you both...",
  ui_story_5088_50881202_48_dialog_content = "<color=#e8d9bb>As this journal reaches its conclusion, what ending would be most fitting?</color>",
  ui_story_5088_50881202_49_dialog_content = "<color=#e8d9bb>Ah, yes, it should go to you, the one who strived so earnestly to reach this point.</color>",
  ui_story_5088_50881202_50_dialog_content = "<color=#e8d9bb>Thank you for making this miracle possible.</color>",
  ui_story_5088_50881202_51_dialog_content = "<color=#e8d9bb>I know this journey has been an arduous one, and in the end, it seems as though your only reward is witnessing the joy of others reuniting.</color>",
  ui_story_5088_50881202_52_dialog_content = "<color=#e8d9bb>But you who have fought so valiantly for others—what reason is there not to acknowledge your greatness?</color>",
  ui_story_5088_50881202_53_dialog_content = "<color=#e8d9bb>May you, who have come this far, also reunite with those who are important to you and find your own joy.</color>",
  ui_story_5088_50881202_54_dialog_content = "<color=#e8d9bb>We wish you happiness from the depths of our hearts, our starlight.</color>",
  ui_story_5088_50881300_1_dialog_content = "<color=#e8d9bb>This is a kingdom that slumbers in the white snow—a serene and peaceful paradise beyond the reach of the world.</color>",
  ui_story_5088_50881300_2_dialog_content = "<color=#e8d9bb>Blessed heroes have dreamt in this frozen land for years, accompanied by the warmest thoughts.</color>",
  ui_story_5088_50881300_3_dialog_content = "<color=#e8d9bb>Beneath this pure world lies buried too much of the past, and what can be seen are only flowers growing from the graves of the sacrificed, guarding a fairy-tale realm.</color>",
  ui_story_5088_50881300_4_dialog_content = "<color=#e8d9bb>Bethlehem closes the book, gazing at the melting barrier in the distance—within the long-frozen realm of Northland, a field of spring flowers blooms.</color>",
  ui_story_5088_50881300_5_dialog_content = "<color=#e8d9bb>The history of Northland begins with the kingdom that first unified it. Legend tells of a king who sat alone on an icy throne, bringing peace to this land.</color>",
  ui_story_5088_50881300_6_dialog_content = "<color=#e8d9bb>Many years later, the king's descendants turned against each other in a quest for power, once again plunging Northland into chaos.</color>",
  ui_story_5088_50881300_7_dialog_content = "<color=#e8d9bb>When a girl from the borderlands witnessed this ravaged world, she vowed to restore its purity.</color>",
  ui_story_5088_50881300_8_dialog_content = "<color=#e8d9bb>Thus, the girl led the people, eventually becoming queen.</color>",
  ui_story_5088_50881300_9_dialog_content = "<color=#e8d9bb>In the ancient tomes sealed by the old king, the queen reads from the story of the \"stars.\"</color>",
  ui_story_5088_50881300_10_dialog_content = "<color=#e8d9bb>Thus, every Bethlehem began to wish for the future of the \"stars.\"</color>",
  ui_story_5088_50881300_11_dialog_content = "Heroes, now, it is spring.",
  ui_story_5088_50881300_12_dialog_content = "...",
  ui_story_5088_50881300_13_dialog_content = "Where are we...?",
  ui_story_5088_50881300_14_dialog_content = "Adras, I think the bread's almost ready.",
  ui_story_5088_50881300_15_dialog_content = "Friegson, turn the heat down!",
  ui_story_5088_50881300_16_dialog_content = "... Someone's been taking sneaky nibbles out of it.",
  ui_story_5088_50881300_17_dialog_content = "Wow, it smells so good...",
  ui_story_5088_50881300_18_dialog_content = "What happened to your noble demeanor?",
  ui_story_5088_50881300_19_dialog_content = "Who cares about that when there's good food to eat?",
  ui_story_5088_50881300_20_dialog_content = "I can help!",
  ui_story_5088_50881300_21_dialog_content = "Hey! You're just trying to grab a cheeky bite while pretending to help out, aren't you? I don't think so!",
  ui_story_5088_50881300_22_dialog_content = "That's a lie! You can't bully me... Ludweiss, help!",
  ui_story_5088_50881300_23_dialog_content = "Who even goes around arguing with children?! Lady Marcela, you must teach her a lesson!",
  ui_story_5088_50881300_24_dialog_content = "Huh? No, no, no, I was just kidding...",
  ui_story_5088_50881300_25_dialog_content = "<color=#FFB400>An illusion</color>...",
  ui_story_5088_50881300_26_dialog_content = "Yes, this is the scene you long for the most.",
  ui_story_5088_50881300_27_dialog_content = "Ludweiss...",
  ui_story_5088_50881300_28_dialog_content = "In this blissful dream, your presence is the only thing missing.",
  ui_story_5088_50881300_29_dialog_content = "And that is enough.",
  ui_story_5088_50881300_30_dialog_content = "Achilles, you are strong enough to recognize that this is a mere illusion, yet weak in fear that you might shatter this happiness.",
  ui_story_5088_50881300_31_dialog_content = "... You won't stop me from leaving, will you?",
  ui_story_5088_50881300_32_dialog_content = "Yes.",
  ui_story_5088_50881300_33_dialog_content = "As this is your fantasy, I should tell you to stay.",
  ui_story_5088_50881300_34_dialog_content = "But I still wish for you to explore the new world for me, and help me pen new tales of your travels.",
  ui_story_5088_50881300_35_dialog_content = "Is it really okay for us to come back to the world like this?",
  ui_story_5088_50881300_36_dialog_content = "Do you believe such a thing to be simple?",
  ui_story_5088_50881300_37_dialog_content = "This isn't a game where victory leads to resurrection.",
  ui_story_5088_50881300_38_dialog_content = "But even so, who wouldn't want to gather around you for a spring reunion? Thus, everyone mustered their might for their hero.",
  ui_story_5088_50881300_39_dialog_content = "And you vowed to find a way to reunite.",
  ui_story_5088_50881300_40_dialog_content = "... You're right.",
  ui_story_5088_50881300_41_dialog_content = "Farewell, Ludweiss.",
  ui_story_5088_50881300_42_dialog_content = "Wait.",
  ui_story_5088_50881300_43_dialog_content = "?!",
  ui_story_5088_50881300_44_dialog_content = "Safe travels.",
  ui_story_5088_50881300_45_dialog_content = "Please watch over Adras for me!",
  ui_story_5088_50881300_46_dialog_content = "Heh...",
  ui_story_5088_50881300_47_dialog_content = "Farewell.",
  ui_story_5088_50881300_48_dialog_content = "... Farewell.",
  ui_story_5088_50881300_49_dialog_content = "<color=#e8d9bb>Northland has never lacked stunning scenery and beautiful flowers, but the people here have never seen such a glorious spring light as this.</color>",
  ui_story_5088_50881300_50_dialog_content = "<color=#e8d9bb>In this small corner of the world, where the ice and snow have finally melted, dandelions dance in the air and fields of flowers bloom brightly.</color>",
  ui_story_5088_50881300_51_dialog_content = "<color=#e8d9bb>A rainbow leans against the Obelisk of Return, listening to its gentle and melodious song.</color>",
  ui_story_5088_50881300_52_dialog_content = "<color=#e8d9bb>Everyone nearby is deeply captivated by it.</color>",
  ui_story_5088_50881300_53_dialog_content = "After two thousand years, our clan's wish has finally come true...",
  ui_story_5088_50881300_54_dialog_content = "Thank you for being part of this world.",
  ui_story_5088_50881300_55_dialog_content = "You flatter me too much...",
  ui_story_5088_50881300_56_dialog_content = "I was completely lost once, but now I understand the greatness of those who came before me.",
  ui_story_5088_50881300_57_dialog_content = "From now on, I will follow the path of justice, just like my ancestors—the path of the Star Warriors.",
  ui_story_5088_50881300_58_dialog_content = "I think you're pretty impressive, Mithra... especially when you saved me that night.",
  ui_story_5088_50881300_59_dialog_content = "Despite your confusion, you never gave up.",
  ui_story_5088_50881300_60_dialog_content = "It was thanks to you that I was able to awaken Achilles. In every situation we faced, you always took the initiative. You've done so much.",
  ui_story_5088_50881300_61_dialog_content = "... Hehe.",
  ui_story_5088_50881300_62_dialog_content = "Maybe you have a point.",
  ui_story_5088_50881300_63_dialog_content = "Then let's go!",
  ui_story_5088_50881300_64_dialog_content = "Huh?",
  ui_story_5088_50881300_65_dialog_content = "To reunite with everyone...",
  ui_story_5088_50881300_66_dialog_content = "Wow, it's so pretty! I've never seen a place like this before.",
  ui_story_5088_50881300_67_dialog_content = "And these flowers...",
  ui_story_5088_50881300_68_dialog_content = "... Children?",
  ui_story_5088_50881300_69_dialog_content = "Stop running around, little girl, or you'll end up getting yourself scratched by all the plants here. Come, I'll show you the prettiest flowers.",
  ui_story_5088_50881300_70_dialog_content = "Hey, lady! You're so tall!",
  ui_story_5088_50881300_71_dialog_content = "Would you like to be tall too?",
  ui_story_5088_50881300_72_dialog_content = "Will this do?",
  ui_story_5088_50881300_73_dialog_content = "Wow! You're lifting me up! I'm taller than everyone now!",
  ui_story_5088_50881300_74_dialog_content = "... If you go running out like this, your parents will start to worry.",
  ui_story_5088_50881300_75_dialog_content = "It's okay, sir, my dad's over there with my mom looking at flowers!",
  ui_story_5088_50881300_76_dialog_content = "Miss, this... is for you...",
  ui_story_5088_50881300_77_dialog_content = "Thank you.",
  ui_story_5088_50881300_78_dialog_content = "...",
  ui_story_5088_50881300_79_dialog_content = "Hey, Mister, aren't you gonna come over?",
  ui_story_5088_50881300_80_dialog_content = "Thank you, but I'll stay here and watch for now.",
  ui_story_5088_50881300_81_dialog_content = "No! Come on, Mister!",
  ui_story_5088_50881300_82_dialog_content = "That ponytail lady said she'll give me lots of yummy candy if I bring you over!",
  ui_story_5088_50881300_83_dialog_content = "... Freya?",
  ui_story_5088_50881300_84_dialog_content = "Heh.",
  ui_story_5088_50881300_85_dialog_content = "Mister, you're smiling!",
  ui_story_5088_50881300_86_dialog_content = "You've got a real friendly smile.",
